INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(123154, 'esES', 'Usa Llamar a mascota para incorporar a tu mascota a la batalla.', '', 25549),
(123152, 'esES', 'Junto a tu fiel mascota, dominas el entorno que te rodea. Llamar a mascota hará que esta corra hasta tu lado.', '', 25549),
(123151, 'esES', 'Los cazadores Supervivencia son muy hábiles en combate cuerpo a cuerpo y cuentan con varios recursos para aniquilar a su presa.', '', 25549),
(123150, 'esES', 'Los cazadores Supervivencia son muy hábiles en combate cuerpo a cuerpo y cuentan con varios recursos para aniquilar a su presa.', '', 25549),
(123149, 'esES', '¡Hay muy poco tiempo! ¡No puedo trabajar en estas condiciones!', '¡Hay muy poco tiempo! ¡No puedo trabajar en estas condiciones!', 25549),
(123148, 'esES', 'A este paso, vamos a necesitar más pintura.', 'A este paso, vamos a necesitar más pintura.', 25549),
(123147, 'esES', '', '¡Farondis no conocerá la paz mientras estemos malditos!', 25549),
(123146, 'esES', '', 'Farondis es el responsable de nuestra maldición... ¡Lo pagará con creces!', 25549),
(123145, 'esES', '¡Usa Ira del chamán!', '', 25549),
(123144, 'esES', '', '¡Usa Ira del chamán!', 25549),
(123143, 'esES', '¡Tus Marchitos se perderán si los dejas atrás!', '¡Tus Marchitos se perderán si los dejas atrás!', 25549),
(123142, 'esES', 'Atención, invitados: ¡MORID! ¡MORID! ¡MORID!', '', 25549),
(123141, 'esES', '¡EXTERMINACIÓN!', '', 25549),
(123140, 'esES', 'Sobrecarga en curso. Preparaos para... ¡PURGAR! ¡PURGAR! ¡PURGAR!', '', 25549),
(123139, 'esES', 'Curator ya no está opera-ti-vo.', '', 25549),
(123138, 'esES', 'La colección es solo para... ¡ERRADICAR! ¡ERRADICAR!', '', 25549),
(123135, 'esES', 'Este vino de arco se ha estropeado... ¡Tienes que volver a empezar!', 'Este vino de arco se ha estropeado... ¡Tienes que volver a empezar!', 25549),
(123134, 'esES', 'El viento huele a sangre.', 'Esta es tu embarcación, $n. Que la Luz te acompañe.', 25549),
(123133, 'esES', '¿Seguro que quieres saltarte la introducción de la Costa Abrupta? Puedes volver a obtener esta misión de la archivista Elysiana en la Ciudad de Dalaran, en las Islas Abruptas.', '¿Seguro que quieres saltarte la introducción de la Costa Abrupta? Puedes volver a obtener esta misión de la archivista Elysiana en la Ciudad de Dalaran, en las Islas Abruptas.', 25549),
(123132, 'esES', 'Ya he oído esta historia... <Saltarse las misiones preliminares de Legion e ir a Dalaran.> ', 'Ya he oído esta historia... <Saltarse las misiones preliminares de Legion e ir a Dalaran.> ', 25549),
(123126, 'esES', '|TInterface\\Icons\\ability_bossfelmagnaron_rune.blp:20|t ¡Odyn empieza a |cFFFF0404|Hspell:227503|h[Extraer poder]|h|r de las runas!', '|TInterface\\Icons\\ability_bossfelmagnaron_rune.blp:20|t ¡Odyn empieza a |cFFFF0404|Hspell:227503|h[Extraer poder]|h|r de las runas!', 25549),
(123124, 'esES', '', '¡Grlmgmmrr!', 25549),
(123123, 'esES', '', 'Mrrmgmrlgmm.', 25549),
(123122, 'esES', '', 'Mlgrmgrlmgrmrrrmgrrr.', 25549),
(123121, 'esES', 'Tanto que cuesta creerlo. ¿No estarás bromeando?', '', 25549),
(123120, 'esES', '', 'Mgrmglrm.', 25549),
(123119, 'esES', 'Lo presentía. Sabía que algo maravilloso tenía que ocurrir y ha ocurrido; más maravilloso de lo que soñé.', '', 25549),
(123118, 'esES', '', 'Grrmgmrlgmrrm.', 25549),
(123117, 'esES', '¿O crees que ya nos conocíamos?', '', 25549),
(123116, 'esES', '', 'Mrgrlglrllrr.', 25549),
(123115, 'esES', '¿No me confundirás con otro?', '', 25549),
(123114, 'esES', '¡BASTA! ¡Habéis probado vuestra valía! Con vosotros como campeones, Helya caerá y al fin seré libre de la maldición que me ata a este lugar.', '', 25549),
(123113, 'esES', 'No puedo ir a la Dalaran del Paso de la Muerte para ayudarte; teletranspórtame directamente a Dalaran en las Islas Abruptas.', 'No puedo ir a la Dalaran del Paso de la Muerte para ayudarte; teletranspórtame directamente a Dalaran en las Islas Abruptas.', 25549),
(123112, 'esES', 'La Legión está atacando Dalaran en el Paso de la Muerte, y con ahínco, al parecer.\n\n¿Y si yo completo el ritual aquí y tú te reúnes con nosotros en las Islas Abruptas?', '', 25549),
(123111, 'esES', '', 'Yo no tengo amigos... Aparte de ti, Galindre.', 25549),
(123110, 'esES', '', '¡Todos merecemos la oportunidad de volar! ¡Eh! ¿Crees que el mago hará que deje de ser verde?', 25549),
(123109, 'esES', '', 'Claro, querida. Aunque, con ese vestido tan anticuado... ¡Mira! Unos amigos han venido a visitarnos.', 25549),
(123108, 'esES', '', 'Elfyra, ¡baja de ahí! ¡Deja de revolotear como uno de esos monos asquerosos!', 25549),
(123106, 'esES', '¡Héroes, comenzad la batalla cuando queráis!', '', 25549),
(123105, 'esES', '¡Hymdall! ¡Hyrja! Probad la valía de estos mortales. Debo asegurarme de que tengan el coraje y la habilidad necesarios.', '', 25549),
(123104, 'esES', '¡Campeones! Habéis derramado la sangre de los esbirros de Helya. Es el momento de entrar en Helheim y poner fin al reinado oscuro de la bruja del mar. Pero antes... ¡un último desafío!', '', 25549),
(123103, 'esES', 'Bien hecho... ¡por ahora! ¡Pero seré yo mismo quien juzgue si sois dignos!', '', 25549),
(123102, 'esES', 'Parece que he sido demasiado gentil. ¡En guardia!', '', 25549),
(123101, 'esES', '|TInterface\\Icons\\Spell_Holy_PrayerOfHealing:20|t¡%s está lanzando |cFFFF0000|Hspell:227508|h[Arrepentimiento en masa]|h|r!', '|TInterface\\Icons\\Spell_Holy_PrayerOfHealing:20|t¡%s está lanzando |cFFFF0000|Hspell:227508|h[Arrepentimiento en masa]|h|r!', 25549),
(123100, 'esES', '|TInterface\\Icons\\Spell_Holy_InnerFire:20|t¡%s te está lanzando |cFFFF0000|Hspell:227789|h[Suelo Sagrado]|h|r!', '|TInterface\\Icons\\Spell_Holy_InnerFire:20|t¡%s te está lanzando |cFFFF0000|Hspell:227789|h[Suelo Sagrado]|h|r!', 25549),
(123099, 'esES', '|cffADFF2F+$1i Reputación con los Caídos de la Noche|r', '|cffADFF2F+$1i Reputación con los Caídos de la Noche|r', 25549),
(123098, 'esES', 'A menos que encontremos otra forma de enfrentarnos a ellos.', '', 25549),
(123097, 'esES', 'El ejército que marcha hacia Azeroth no es más que un atisbo de la verdadera fuerza de la Legión.', '', 25549),
(123096, 'esES', '', 'Te he fallado, Sargeras...', 25549),
(123095, 'esES', 'Deberíamos dividir nuestros esfuerzos. Yo intentaré sortear las defensas mágicas de la torre, pero también necesitaremos algo más radical.', '', 25549),
(123078, 'esES', 'Te concederé una muerte rápida.', 'Te concederé una muerte rápida.', 25549),
(123077, 'esES', 'He matado a otros cientos antes que a ti. Tu muerte será una más.', 'He matado a otros cientos antes que a ti. Tu muerte será una más.', 25549),
(123076, 'esES', 'Tu sangre ensuciará mi hoja, ¡como la de tantos otros!', 'Tu sangre ensuciará mi hoja, ¡como la de tantos otros!', 25549),
(123075, 'esES', '¡No nos gustan los de tu calaña!', '¡No nos gustan los de tu calaña!', 25549),
(123074, 'esES', '¡No hay lugar para ti en este mundo!', '¡No hay lugar para ti en este mundo!', 25549),
(123073, 'esES', '¡No pasarás de aquí!', '¡No pasarás de aquí!', 25549),
(123072, 'esES', '¡Me he estado entrenando para esto!', '¡Me he estado entrenando para esto!', 25549),
(123071, 'esES', '¡Intrusos! ¡Dad la alarma!', '¡Intrusos! ¡Dad la alarma!', 25549),
(123069, 'esES', '', '¡Menuda conmoción!', 25549),
(123068, 'esES', '', 'Por primera vez me siento... waku.', 25549),
(123067, 'esES', '', '¿Has perdido la waku cabeza?', 25549),
(123066, 'esES', '', 'Necesitaba un cambio de imagen.', 25549),
(123065, 'esES', '', '¡Elekkamomen otunbuntu rotu kelaramen!', 25549),
(123064, 'esES', '', '¡Observad a mis esbirros, escuchadlos!', 25549),
(123063, 'esES', '', '¡Merecéis la oportunidad de volar!', 25549),
(123062, 'esES', '', '¡Lamento bajaros de las nubes!', 25549),
(123061, 'esES', '', '¡Seguid mi ejemplo y seréis populares!', 25549),
(123060, 'esES', '', '¡Juntas, somos insuperables!', 25549),
(123055, 'esES', '', '|TInterface\\Icons\\spell_arcane_arcanetorrent_nightborne:20|t¡Galindre está lanzando |cFFFF0404|Hspell:227776|h[Magnífico mágico]|h|r! ¡Usa los vórtices de |TInterface\\Icons\\spell_priest_void blast:20|t|cFFFF0404|Hspell:227405|h[Desafiar la gravedad]|h|r para escapar!', 25549),
(123054, 'esES', 'En marcha.', 'En marcha.', 25549),
(123053, 'esES', '', '¿$GListo:Lista; para empezar?', 25549),
(123052, 'esES', 'Esa bruja jurunga no es de mi gusto, pero la de antes daba más susto.', '', 25549),
(123051, 'esES', 'Esta noche vosotros ven dingue función, un kuento rancio ke mola un montón.', '', 25549),
(123050, 'esES', '¡Cierra el piko, miko dramas! ¡El Rey Mono domina el panorama!', '', 25549),
(123049, 'esES', 'Señoras y señores, bienvenidos a nuestra... ¡AY!', '', 25549),
(123048, 'esES', '¿Cuál es la misión?', '¿Cuál es la misión?', 25549),
(123047, 'esES', '', 'Cuento contigo, $n.', 25549),
(123046, 'esES', '', 'Qué bello y... trágico.', 25549),
(123045, 'esES', '', '¡Este sitio necesita el toque Galindre!', 25549),
(123044, 'esES', '', '¡Y ahora, algo aún más espectacular!', 25549),
(123043, 'esES', '¡El signo estelar de %s se ha agotado y se ha activado un Gran trígono!', '¡El signo estelar de %s se ha agotado y se ha activado un Gran trígono!', 25549),
(123042, 'esES', '¡%s y $n han chocado y se ha activado un Gran trígono!', '¡%s y $n han chocado y se ha activado un Gran trígono!', 25549),
(123040, 'esES', '¡Salta por encima del efecto para evitar el daño de |cFFFF0404|Hspell:211901|h[Prensa de fusión]|h|r!', '¡Salta por encima del efecto para evitar el daño de |cFFFF0404|Hspell:211901|h[Prensa de fusión]|h|r!', 25549),
(123039, 'esES', '<Montar en Picobravo.>', '<Montar en Picobravo.>', 25549),
(123038, 'esES', '<Picobravo te mira con recelo.>', '', 25549),
(123037, 'esES', '¡El amor es un ideal anticuado que nace de una reacción instintiva!', '¡El amor es un ideal anticuado que nace de una reacción instintiva!', 25549),
(123036, 'esES', '¡No pienso volver al cuarto del correo!', '¡No pienso volver al cuarto del correo!', 25549),
(123035, 'esES', '¡No me pagan lo suficiente para esto!', '¡No me pagan lo suficiente para esto!', 25549),
(123033, 'esES', 'Sientes que una presencia impactante al otro lado del portal te toca durante un instante...', 'Sientes que una presencia impactante al otro lado del portal te toca durante un instante...', 25549),
(123030, 'esES', '¿Tienes otro silbato de maestro de vuelo?', '¿Tienes otro silbato de maestro de vuelo?', 25549),
(123029, 'esES', 'You must be below level 101 to participate in Legion Invasions.', 'You must be below level 101 to participate in Legion Invasions.', 25549),
(123028, 'esES', '|TInterface\\Icons\\ability_mage_arcanebarrage_nightborne:20|t¡Eres el objetivo de |cFFF00000|Hspell:220871|h[Maná inestable]|h|r!', '', 25549),
(123027, 'esES', 'Tengo que saltar a la arena para destruir a esa monstruosidad. Madre Luna, dame fuerza.', '', 25549),
(123026, 'esES', 'La Espada de Ébano prevalecerá. Nadie se interpondrá en nuestro camino... y vivirá para contarlo.', '', 25549),
(123024, 'esES', '¡El Anillo de la Tierra está contigo, Clarividente! ¡Nos enfrentaremos a la Legión Ardiente a toda costa!', '', 25549),
(123023, 'esES', 'Me gustaría reclutar a algunas tropas de la Cosecha Oscura.', 'Me gustaría reclutar a algunas tropas de la Cosecha Oscura.', 25549),
(123021, 'esES', '¡Vamos dentro!', '¡Vamos dentro!', 25549),
(123020, 'esES', '¿Estás $glisto:lista; para entrar en el Planetario?', '', 25549),
(123019, 'esES', 'Estoy listo para partir hacia Karazhan.', 'Estoy lista para partir hacia Karazhan.', 25549),
(123018, 'esES', '¡Debes acompañar a Khadgar y encontrar los Pilares, $n!', '', 25549),
(123017, 'esES', '¡Salvemos a Magni!', '¡Salvemos a Magni!', 25549),
(123016, 'esES', '¿Estás $glisto:lista; para que disipe esta barrera?', '', 25549),
(123014, 'esES', '¿Brann Barbabronce? Menuda sorpresa.', '', 25549),
(123013, 'esES', 'Danos tiempo para prepararnos, $n.$b$bProtege la ciudad de la Legión o usa tu mapa para encontrar una invasión que detener.$b$bCuando llegue el momento, te avisaré.', '', 25549),
(123012, 'esES', 'Te ayudaré en todo lo que pueda. Es un honor servir al Kirin Tor.', '', 25549),
(123011, 'esES', '', 'Nunca habíamos trasladado Dalaran dos veces en tan poco tiempo.', 25549),
(123010, 'esES', 'Debemos reunir nuestras fuerzas. El hechizo para trasladar la ciudad será agotador.', '', 25549),
(123009, 'esES', 'Ahora debo atender a otros visitantes. ¡Buena suerte, $n!', '', 25549),
(123008, 'esES', 'Me han llegado rumores sobre unos poderosos artefactos que pueden ser útiles en tu campaña. ¡Quizás descubras una pista útil!', '', 25549),
(123007, 'esES', 'Los recursos de Dalaran están a tu disposición. Desde aquí, los héroes de la Alianza y de la Horda buscarán los Pilares de la Creación.', '', 25549),
(123006, 'esES', '', '|TInterface\\Icons\\Spell_Shadow_Possession:20|t %s empieza a lanzar |cFFFF0000|Hspell:227233|h[Bramido corrupto]|h|r. ¡Cuidado!', 25549),
(123005, 'esES', 'Caza esto...', '', 25549),
(123004, 'esES', 'Adiós... y buena suerte. La próxima vez quizás os vaya mejor si suplicáis por vuestras vidas.', '', 25549),
(123003, 'esES', 'No derrotaremos a la Legión mientras los cobardes como tú lleven las riendas.', '', 25549),
(123002, 'esES', '¡Eres un necio, Cresta Cuervo! Da igual, no puedo aprender nada más de ti.', '', 25549),
(123001, 'esES', '¿Y osáis cuestionar mis métodos? Mis magos han muerto para salvar nuestro mundo. ¿Qué habéis hecho vosotros? ¿Qué habéis sacrificado?', '', 25549),
(123000, 'esES', 'Esto era una invasión. Casi nos matan a todos y toman Suramar.', '', 25549),
(122999, 'esES', '¿Haber qué? ¡Estás ciego, Cresta Cuervo! ¡Estáis todos ciegos!', '', 25549),
(122998, 'esES', '¡Siempre hay elección! Podríamos haber...', '', 25549),
(122997, 'esES', '¿Qué querías que hiciera, Kur''talos? ¿Arrodillarme ante nuestros nuevos amos de la Legión mientras reducían nuestro mundo a cenizas?', '', 25549),
(122996, 'esES', '¿Acaso no somos mejores que los monstruos a los que nos enfrentamos?', '', 25549),
(122995, 'esES', 'Qué barbaridad...', '', 25549),
(122994, 'esES', '¡No puede ser!', '', 25549),
(122993, 'esES', '¡Illidan, no!', '', 25549),
(122992, 'esES', 'Que la Madre Luna me perdone...', '', 25549),
(122991, 'esES', '¡Illidan, haz algo! ¡Nos está destrozando! ¡El fuerte no resistirá mucho más!', '', 25549),
(122990, 'esES', 'Lo he probado todo con esta criatura y no sirve nada. Debo recurrir a mi Guardia Lunar una última vez.', '', 25549),
(122989, 'esES', '¡Nos uniremos a la batalla en la arena! ¡Capitán Tempestira, dirige el ataque!', '', 25549),
(122988, 'esES', '¡Illidan ha tomado el patio! ¡Guardia del Torreón, avanzad!', '', 25549),
(122987, 'esES', '¡Soy el mejor cazador de magos de todo el cosmos! ¡No tienes ninguna posibilidad!', '', 25549),
(122986, 'esES', '¿Necesitah máh entrenamiento?', '', 25549),
(122985, 'esES', '|TInterface\\Icons\\spell_shadow_zdemonformgreen:20|t¡%s lanza |cFFFF0000|Hspell:199193|h[Argucia de Señor del Terror]|h|r!', '|TInterface\\Icons\\spell_shadow_zdemonformgreen:20|t¡%s lanza |cFFFF0000|Hspell:199193|h[Argucia de Señor del Terror]|h|r!', 25549),
(122984, 'esES', '', 'No te preocupes, joven. Soy tu jefa de guerra.', 25549),
(122983, 'esES', '', 'Ahora lucho por la Horda.', 25549),
(122982, 'esES', '', 'No me hace falta defensa, $gembajador:embajadora;. Joven, el manto de jefa de guerra es pesado, pero se me eligió para llevar esa carga.', 25549),
(122981, 'esES', 'Mi amigo del orfanato dijo que elegirías a los Renegados antes que a la Horda y que nos abandonarías. ¿Es verdad?', '', 25549),
(122980, 'esES', 'Habla conmigo cuando quieras empezar, $n.', '', 25549),
(122979, 'esES', 'Gracias, colega. Espero que tengas razón.', '', 25549),
(122978, 'esES', 'Es más que una piedra preciosa. Es nuestro rey.', '', 25549),
(122977, 'esES', 'Ya no está, colega. Se fue a obedecer una llamada más importante.', '', 25549),
(122976, 'esES', 'Bueno, si es un diamante, seguro que está bien. ¡Los diamantes son duros!', '', 25549),
(122975, 'esES', '¿El diamante se ha ido andando?', '', 25549),
(122974, 'esES', '¿Dónde está el gran diamante?', '', 25549),
(122973, 'esES', 'Debes darte prisa para encontrarlos. En manos de la Legión, los Pilares de la Creación podrían ser devastadores para nuestro mundo. Buena suerte.', '', 25549),
(122972, 'esES', 'Gracias, Guardián. Has servido a Azeroth una vez más.', '', 25549),
(122971, 'esES', '', 'Al menos sabemos por dónde empezar. Peinaremos todas las Islas Abruptas si es necesario.', 25549),
(122970, 'esES', 'Muy bien. Mi investigación me llevó hasta las Islas Abruptas. Aunque nunca llegué a encontrar sus ubicaciones exactas, creo que los Pilares están en manos de la gente de esa tierra ancestral.', '', 25549),
(122969, 'esES', 'Es vital encontrar estos artefactos. Los Pilares son lo único que puede sellar el portal de la Legión de la Tumba de Sargeras.', '', 25549),
(122968, 'esES', '¡Por supuesto que no! Los pilares representan un poder primordial. Incluso como guardián, no me atreví a jugar con ellos.', '', 25549),
(122967, 'esES', '', 'Estamos buscando cinco artefactos antiguos llamados los Pilares de la Creación. En tus apuntes no especificaste dónde encontrarlos.', 25549),
(122966, 'esES', 'Qué pena que no se vea Tormenheim.', '', 25549),
(122965, 'esES', '¿Has leído mi trabajo? Creía que las nuevas generaciones ya no leían libros. Que siempre estaban jugando o de aventuras...', '', 25549),
(122964, 'esES', 'La Legión Ardiente ha regresado. Para detenerla, hemos peinado la biblioteca de Karazhan en busca de un tomo que titulaste "Antigüedades notables del antiguo Azeroth".', '', 25549),
(122963, 'esES', 'Te conozco. El aprendiz que rechaza el manto que yo llevé. ¿Qué necesitas de mí?', '', 25549),
(122962, 'esES', 'Saludos, Alodi. Soy Khadgar, archimago del Kirin...', '', 25549),
(122961, 'esES', '¡Una invocación! Hace siglos que no me piden ayuda.', '', 25549),
(122960, 'esES', '¡Invoco al espíritu del Primer Guardián!', '', 25549),
(122959, 'esES', 'Casi no me queda energía. Necesito un portal para descansar o tendré que succionar la esencia de mi Guardia Lunar.', '', 25549),
(122958, 'esES', 'Jamás había sentido semejante poder... semejante agonía.', '', 25549),
(122957, 'esES', 'Un eredar llamado Balaadur protege el portal a Nihilam. Los hechizos corrientes son inútiles contra él. Tendré que invocar la furia del cosmos para destruir el portal. Entonces solo quedaremos el demonio y yo.', '', 25549),
(122956, 'esES', 'Hay demasiados demonios. Necesitaré más poder de mi Guardia Lunar. ¿Me estaré extralimitando? No, ¡debo centrarme! ¡El futuro de mi gente está en mis manos!', '', 25549),
(122955, 'esES', '¿Cómo osas enfrentarte a la gran sombra ardiente? Esbirros, ¡atacad!', '', 25549),
(122954, 'esES', '¡No dejan de llegar más! Parece que las tropas demoníacas están entrando por el portal del patio que hay más abajo. Si no lo destruyo, no sobreviviremos, pero necesitaré la ayuda de mi Guardia Lunar.', '', 25549),
(122953, 'esES', '¡Soy Illidan! Temblad ante mí, ¡pues seré vuestra perdición!', '', 25549),
(122952, 'esES', '¡Debo poner fin a esto!', '', 25549),
(122951, 'esES', '¿Quién puede hacer frente a un ejército así?', '', 25549),
(122950, 'esES', '¡Debo encontrar la forma de cerrar el portal!', '', 25549),
(122949, 'esES', '¡Cada vez que mato a un demonio aparecen dos más!', '', 25549),
(122948, 'esES', '¡No dejan de venir!', '', 25549),
(122947, 'esES', 'Quizás el viento haya despejado la niebla.', '', 25549),
(122946, 'esES', '¡Desde aquí se ve todo Suramar!', '', 25549),
(122945, 'esES', 'Mejor no repetir esto nunca.', 'Mejor no repetir esto nunca.', 25549),
(122944, 'esES', 'He sido descuidado y, por ello, debo retirarme, pero aprenderé de esta derrota... y me vengaré.', '', 25549),
(122943, 'esES', 'Malfurion será el druida principal porque es un estudiante aplicado. Tú no lo eres.', '', 25549),
(122942, 'esES', 'Invocaré al espíritu de Alodi, el primer guardián de Tirisfal. Avísame cuando quieras que empiece.', '', 25549),
(122941, 'esES', 'Comienza la invocación.', 'Comienza la invocación.', 25549),
(122940, 'esES', 'Derrotaremos a la Legión.', '', 25549),
(122939, 'esES', 'Dalaran no caerá, $n.', '', 25549),
(122938, 'esES', '¡Hay que frenar a la Legión!', '', 25549),
(122937, 'esES', 'Esto no es una mala idea EN ABSOLUTO.', 'Esto no es una mala idea EN ABSOLUTO.', 25549),
(122936, 'esES', '¡El maestro de seis ojos ha visto tu destino, $n! ¡Fracasarás y los mundos arderán!', '', 25549),
(122935, 'esES', 'Si quieres seguir estudiando los bosques, podrás hacerlo con tu hermano.', '', 25549),
(122934, 'esES', 'He traído todos mis pedruscos para las catapultas. ¡Gregg quiere unirse a la Horda!', 'Esta es tu embarcación, $n. Que la Luz te acompañe.', 25549),
(122933, 'esES', '¡$n añade veneno al frasco de la noche solemne!', '¡$n añade veneno al frasco de la noche solemne!', 25549),
(122932, 'esES', '¡$n destruye el conducto de poder Arcano, lo que sobrecarga todos los ensamblajes guardianes!', '¡$n destruye el conducto de poder Arcano, lo que sobrecarga todos los ensamblajes guardianes!', 25549),
(122930, 'esES', '¡$n interpreta el pergamino encharcado, lo que otorga velocidad de movimiento aumentada a todos!', '¡$n interpreta el pergamino encharcado, lo que otorga velocidad de movimiento aumentada a todos!', 25549),
(122929, 'esES', '¡$n dirige la energía al farol mágico, lo que otorga daño aumentado a todos!', '¡$n dirige la energía al farol mágico, lo que otorga daño aumentado a todos!', 25549),
(122928, 'esES', '¡$n interactúa con los refrigerios Sombranoche, lo que otorga salud aumentada a todos!', '¡$n interactúa con los refrigerios Sombranoche, lo que otorga salud aumentada a todos!', 25549),
(122927, 'esES', '¡$n libera las esporas de la flor umbría, lo que otorga celeridad aumentada a todos!', '¡$n libera las esporas de la flor umbría, lo que otorga celeridad aumentada a todos!', 25549),
(122926, 'esES', '¡$n absorbe el orbe vil, lo que otorga probabilidad de golpe crítico aumentada a todos!', '¡$n absorbe el orbe vil, lo que otorga probabilidad de golpe crítico aumentada a todos!', 25549),
(122925, 'esES', '¡$n destruye el tomo infernal, lo que otorga reducción de daño a todos!', '¡$n destruye el tomo infernal, lo que otorga reducción de daño a todos!', 25549),
(122924, 'esES', '¡$n interactúa con la cerveza de rosa luz estelar, lo que otorga restauración de salud y maná a todos!', '¡$n interactúa con la cerveza de rosa luz estelar, lo que otorga restauración de salud y maná a todos!', 25549),
(122923, 'esES', '¿Puedes oír ya el fragor de la batalla, $n? ¡Te está llamando!', '', 25549),
(122912, 'esES', '¡La guerra hace que me hierva la sangre, $n! ¿Tu hacha no ansía batirse en duelo?', '', 25549),
(122911, 'esES', 'Sangre y truenos, $n. Tu nave y una gloriosa victoria te aguardan.', 'Esta es tu embarcación, $n. Que la Luz te acompañe.', 25549),
(122908, 'esES', 'Mmm... Eso me da una idea... Hablaremos de ella cuando hayas despachado estas anomalías.', '', 25549),
(122907, 'esES', 'La archimaga Modera y yo seguiremos examinando el tomo que recuperamos de Karazhan. ¡Encontraremos esos pilares, $n!', '', 25549),
(122906, 'esES', 'Qué alivio haber salido ambos enteros de Karazhan.', '', 25549),
(122900, 'esES', '|TInterface\\Icons\\Spell_Holy_HolyNova:20|t¡Hyrja empieza a lanzar |cFFFF0404|Hspell:192206|h[Santificar]|h|r!', '|TInterface\\Icons\\Spell_Holy_HolyNova:20|t¡Hyrja empieza a lanzar |cFFFF0404|Hspell:192206|h[Santificar]|h|r!', 25549),
(122899, 'esES', '|TInterface\\Icons\\Spell_Nature_EyeOfTheStorm:20|t¡Hyrja empieza a lanzar |cFFFF0404|Hspell:192305|h[Ojo de la tormenta]|h|r!', '|TInterface\\Icons\\Spell_Nature_EyeOfTheStorm:20|t¡Hyrja empieza a lanzar |cFFFF0404|Hspell:192305|h[Ojo de la tormenta]|h|r!', 25549),
(122898, 'esES', 'Tenías razón, demonio. La magia vil es más poderosa que la Arcana, ¡pero la manejas con torpeza! ¡Contempla la destrucción que puede causar en manos de un maestro!', '', 25549),
(122897, 'esES', '', '¿Osas desafiar a la Legión Ardiente? ¡Arrodíllate ante el inigualable poder vil!', 25549),
(122896, 'esES', 'No tengo opción. Si fracaso, Suramar caerá mañana, y con ella mi amada Tyrande. ¡Debo actuar ya!', '', 25549),
(122895, 'esES', 'Su magia vil es demasiado fuerte. Podría intentar extraer energía de mi Guardia Lunar y usarla para aniquilar a este demonio, pero mis magos también morirían.', '', 25549),
(122894, 'esES', 'Archimago, debemos irnos.', 'Archimago, debemos irnos.', 25549),
(122893, 'esES', '¡A tus órdenes, Capitán!', '¡A tus órdenes, Capitán!', 25549),
(122892, 'esES', '¡Bajad la puerta y preparaos! ¡Lanzagujas, en posición!', '', 25549),
(122891, 'esES', '¡Estoy listo, lord Cresta Cuervo! ¡Bajad el rastrillo!', '', 25549),
(122890, 'esES', '¡Excelente! El poder que irradia el portal me potenciará mientras permanezca cerca. Debo recordar volver a estos portales cuando esté cansado.', '', 25549),
(122889, 'esES', 'Illidan reflexiona.', '', 25549),
(122888, 'esES', 'Si logro reparar el portal desactivado, obtendré los refuerzos que preciso y una fuente de poder para recargar mi energía.', '', 25549),
(122887, 'esES', 'Ha hecho falta casi toda nuestra energía para invocar esa barrera protectora. Si llevo a la Guardia Lunar al límite, perecerán.', '', 25549),
(122886, 'esES', '¡No te fallaré, mi señor!', '', 25549),
(122884, 'esES', 'Y pienso encontrar esa forma.', '', 25549),
(122883, 'esES', 'Estamos condenados...', '', 25549),
(122882, 'esES', 'Aunque los derrotemos aquí, no cambiará nada.', '', 25549),
(122881, 'esES', 'Tras este ejército hay otro, y otro, y otro...', '', 25549),
(122880, 'esES', 'Nuestros ojos... nos traicionan.', '', 25549),
(122879, 'esES', 'No importa cuánto se resista este mundo; al final, caerá.', '', 25549),
(122878, 'esES', '<Gritos de agonía.>', '', 25549),
(122877, 'esES', 'Contemplad el poder de la Legión.', '', 25549),
(122876, 'esES', 'Hermano...', '', 25549),
(122875, 'esES', 'Recorrer este camino exige sacrificio, Illidan... Es algo que tú aún no has comprendido.', '', 25549),
(122874, 'esES', 'Debes aprender a respetar.', '', 25549),
(122873, 'esES', '¿Así que tengo que aprender de un novicio en lugar de un maestro?', '', 25549),
(122872, 'esES', 'Así que...', '', 25549),
(122871, 'esES', 'No. Puedes quedarte aquí, pero ya no seré tu maestro.', '', 25549),
(122870, 'esES', '¡Me has desterrado, Cenarius!', '', 25549),
(122869, 'esES', 'Illidan, no me conviertas en el blanco de tu ira. No te he insultado.', '', 25549),
(122868, 'esES', '', 'Es verdad. A este niño le espera un destino grandioso y próspero. Su nombre es Illidan.', 25549),
(122867, 'esES', '¡Ese! ¡Tiene los ojos dorados!', '', 25549),
(122866, 'esES', '', 'Qué preciosidad. Casi idénticos salvo por...', 25549),
(122865, 'esES', '', 'Los gemelos Tempestira.', 25549),
(122864, 'esES', '¿Dos?', '', 25549),
(122862, 'esES', '', '¡Corre, pequeño Cresta Cuervo, corre! ¡Puede que aún estés a tiempo de huir y pasar el resto de tus patéticos días subido al algún árbol!', 25549),
(122861, 'esES', '', 'El cachorro... tiene colmillos...', 25549),
(122860, 'esES', '', 'Has... ¿¡Has matado a tus propios soldados!? ¡Menudo necio! ¡Has sellado tu propio destino!', 25549),
(122859, 'esES', '', '¿Qué es esto? ¿Cresta Cuervo envía un cachorro para enfrentarse a mí? ¡Te enseñaré a respetar a tus superiores!', 25549),
(122858, 'esES', '¡$n! ¡Khadgar! ¡Gracias a la Forja que os he encontrado! ¡No os lo vais a creer! ¡Mi hermano Magni ha vuelto!', '', 25549),
(122857, 'esES', '¡El capitán Tempestira nos ha dado una oportunidad! ¡Defended la muralla, Guardia del Torreón! ¡En marcha!', '', 25549),
(122856, 'esES', '¡Haz lo que debas! ¡Si cae el Torreón Grajo Negro, toda Suramar caerá con él!', '', 25549),
(122855, 'esES', '', '%s encoge los hombros con indiferencia y te lanza por los aires de una patada.', 25549),
(122854, 'esES', '', 'Tu funeral.', 25549),
(122853, 'esES', '', '¡$gLADRÓN:LADRONA;! ¡¿Cómo te atreves a robar lo que es mío?!', 25549),
(122852, 'esES', '¡Eres nuestra última esperanza, Illidan!', '', 25549),
(122851, 'esES', 'La Legión ha aniquilado a la mitad de nuestras fuerzas y el resto se ha desperdigado. Lo que ves aquí es todo lo que queda de la Guardia del Torreón, solo ellos lo protegen.', '', 25549),
(122850, 'esES', 'Me gustaría enfrentarme de nuevo a Perdición, maestra.', 'Me gustaría enfrentarme de nuevo a Perdición, maestra.', 25549),
(122849, 'esES', 'Bien hecho, Illidan, pero la batalla solo acaba de empezar.', '', 25549),
(122848, 'esES', '¿Son estas tus iniciales?', '¿Son estas tus iniciales?', 25549),
(122847, 'esES', '', '¿Qué quieres de mí, $r?', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(122846, 'esES', '', 'El nacimiento... no de uno, sino de dos niños sanos.', 25549),
(122845, 'esES', '', 'Loada sea la diosa. Esta noche nos ha bendecido con nueva vida.', 25549),
(122844, 'esES', 'Illidan está muerto, y el Ejército Dorado libra una guerra interminable en nuestro nombre a través del cosmos.', '', 25549),
(122843, 'esES', 'En cuanto al Ejército de la Luz e Illidan, estoy confuso. Nunca me había sentido tan desvalido.', '', 25549),
(122842, 'esES', 'Hemos estado solos todo este tiempo. Nuestros dioses fueron asesinados antes de que hubiéramos nacido.', '', 25549),
(122841, 'esES', 'Eso explica muchas cosas, pero no puedo evitar sentir una tristeza sobrecogedora.', '', 25549),
(122840, 'esES', '¿Muertos? ¿Los titanes están muertos?', '', 25549),
(122838, 'esES', '', 'Habla.', 25549),
(122837, 'esES', '<Enseñar la marca de Thalyssra a Valtrois.>', '<Enseñar la marca de Thalyssra a Valtrois.>', 25549),
(122836, 'esES', '', 'Los ecos de magia se han apagado. Gracias.', 25549),
(122835, 'esES', '', '¡Esos magos fantasmas entrometidos han logrado conjurar un ser de magia salvaje! Dales una lección.', 25549),
(122834, 'esES', '', 'Bien hecho. Podemos estar tranquilos... de momento.', 25549),
(122833, 'esES', '', 'Una bestia gigante se ha alzado de las aguas. ¡Mándala de vuelta al abismo!', 25549),
(122832, 'esES', '¡Lo he visto todo! ¡Illidan! ¡Cresta Cuervo quiere que tome el mando! ¡Tenemos que coordinar nuestro ataque e instaurar cierto orden!', '', 25549),
(122831, 'esES', '¡Quedas relevado de tus funciones, Illidan! ¡Rhonin, la Guardia Lunar es tuya!', '', 25549),
(122830, 'esES', '¿¡QUÉ HAS HECHO!? ¡LOS HAS MATADO A TODOS, ILLIDAN!', '', 25549),
(122829, 'esES', '¡Estad alerta por si veis al capitán Cantosombrío y a sus dos aliados extranjeros! Nos separamos cuando comenzó el ataque. ¡Espero que sigan con vida!', '', 25549),
(122828, 'esES', '¡Y encima esa monstruosidad que hay en la arena quemará el torreón desde dentro si no la detenemos! ¡Coge a tu Guardia Lunar y libera el Torreón Grajo Negro de esta invasión demoníaca!', '', 25549),
(122827, 'esES', '', 'Tyrande... Nosotros le damos tanta importancia al mundo como los seres que lo habitan. Incluso al final, Illidan la veía con la misma claridad que la primera vez que se fijó en ella. Nunca perdió de vista su mundo. Pregúntate hasta dónde irías tú por el tuyo.', 25549),
(122826, 'esES', '', 'Illidan no vaciló ni cuando le quemaron los ojos para ver la verdad. Incluso bajo la mirada del señor de la Legión Ardiente, Illidan se mantuvo firme y desafiante.', 25549),
(122825, 'esES', '', 'Hubo que tomar decisiones difíciles, pero, para cumplir nuestra misión, debemos entender el punto de vista de Illidan. ¿Qué habrías hecho diferente?', 25549),
(122824, 'esES', '', 'Pocos han conocido tal fracaso y rechazo. La mayoría se habría rendido, pero Illidan perseveró, guiado por la mano invisible del destino. Otra suerte le aguardaba.', 25549),
(122823, 'esES', '', 'Illidan rebosaba potencial. Su destino se forjó en la gran ordenación y se desperdigó entre los vientos cósmicos, hasta que halló un hogar en Azeroth. En ese pequeño recipiente, el gran ciclo comenzó de nuevo.', 25549),
(122822, 'esES', '', 'Un antiguo recuerdo despierta. Llámame cuando todo esté listo y desvelaremos una parte del pasado de Illidan.', 25549),
(122821, 'esES', '|TInterface\\Icons\\sha_spell_warlock_demonsoul_nightmare:20|tUsa el |cFF00FFFF|Hspell:212630|h[Suelo Purificante]|h|r de Malfurion para evitar el daño de |cFFFF0000|Hspell:210279|h[Pesadillas espeluznantes]|h|r.', '|TInterface\\Icons\\sha_spell_warlock_demonsoul_nightmare:20|tUsa el |cFF00FFFF|Hspell:212630|h[Suelo Purificante]|h|r de Malfurion para evitar el daño de |cFFFF0000|Hspell:210279|h[Pesadillas espeluznantes]|h|r.', 25549),
(122820, 'esES', '¡Surcar los cielos es un auténtico placer!', '', 25549),
(122819, 'esES', '¡Lo sabía! ¡Lo notaba!$b$b¡Despeja la ciudad, $n! ¡Debemos retenerlos!', '', 25549),
(122818, 'esES', '', '¡Hacedlos retroceder! ¡No podemos dejar que Dalaran caiga!', 25549),
(122817, 'esES', '¡Que el rápido acero sea tu final!', '', 25549),
(122816, 'esES', '¡Fracasarás en tus esfuerzos!', '', 25549),
(122815, 'esES', 'Estoy igual de sorprendido que tú, $n.', '', 25549),
(122814, 'esES', '¡Este será tu final!', '', 25549),
(122813, 'esES', '¡Que mi hoja te purifique!', '', 25549),
(122812, 'esES', '', 'Hazlo lo mejor que puedas, $n. Intentaremos aguantar a estos demonios todo lo posible.', 25549),
(122811, 'esES', 'Soy el archimago Khadgar, líder del Kirin Tor. Cazadores de demonios, Azeroth necesita vuestra ayuda.', '', 25549),
(122810, 'esES', 'Tenía un plan muy elaborado para salir de aquí, pero creo que me has ganado.', '', 25549),
(122809, 'esES', '¡Estamos todos condenados!', '¡Estamos todos condenados!', 25549),
(122808, 'esES', '¡La Luz se ha apagado! ¿No lo ves?', '¡La Luz se ha apagado! ¿No lo ves?', 25549),
(122807, 'esES', '', '¡Estas cosas no dejan de venir!', 25549),
(122806, 'esES', '¡Nada de lo que hagas podrá detenerlos!', '¡Nada de lo que hagas podrá detenerlos!', 25549),
(122805, 'esES', '¡Sin él, todos estaríamos perdidos!', '¡Sin él, todos estaríamos perdidos!', 25549),
(122804, 'esES', '¡Va por ti, $n!', '', 25549),
(122803, 'esES', '¡Fuera de nuestras tiendas!', '', 25549),
(122802, 'esES', '¡Ni hablar!', '', 25549),
(122801, 'esES', '', '$GBendito:Bendita; seas...', 25549),
(122800, 'esES', '', 'Vuelvo... a la oscuridad del más allá...', 25549),
(122799, 'esES', '', 'Libre... al fin...', 25549),
(122798, 'esES', '', 'Muchas... gracias...', 25549),
(122797, 'esES', '', 'Estoy... perdida...', 25549),
(122796, 'esES', '', 'La Luz se ha apagado...', 25549),
(122795, 'esES', '', 'No hay esperanza...', 25549),
(122794, 'esES', '', 'Ayúda... me...', 25549),
(122793, 'esES', '¿Es que nadie puede controlarlos?', '¿Es que nadie puede controlarlos?', 25549),
(122792, 'esES', '¡Que alguien detenga esto!', '¡Que alguien detenga esto!', 25549),
(122791, 'esES', '¡Quítame esto de encima!', '¡Quítame esto de encima!', 25549),
(122790, 'esES', '¡Llegan refuerzos, maestro Illidan!', '', 25549),
(122789, 'esES', '[%s] confiesa: Siempre pongo las cosas más baratas que los demás en la casa de subastas, porque puedo.', '[%s] confiesa: Siempre pongo las cosas más baratas que los demás en la casa de subastas, porque puedo.', 25549),
(122788, 'esES', '[%s] confiesa: No me gusta enfrentarme a los gronns, siempre parece que me están mirando fijamente.', '[%s] confiesa: No me gusta enfrentarme a los gronns, siempre parece que me están mirando fijamente.', 25549),
(122787, 'esES', '¡Por fin, un oponente digno de mi hacha!', '', 25549),
(122786, 'esES', '[%s] confiesa: Garrosh me parecía agradable.', '[%s] confiesa: Garrosh me parecía agradable.', 25549),
(122785, 'esES', '[%s] confiesa: Me gusta mucho la posada de Villadorada.', '[%s] confiesa: Me gusta mucho la posada de Villadorada.', 25549),
(122784, 'esES', '[%s] confiesa: No entiendo por qué se llaman Islas Abruptas. ¿No son abruptas todas las islas?', '[%s] confiesa: No entiendo por qué se llaman Islas Abruptas. ¿No son abruptas todas las islas?', 25549),
(122783, 'esES', '[%s] confiesa: Esperaba en secreto que un barco en concreto de mi astillero fracasara en su misión. Nunca lo hizo.', '[%s] confiesa: Esperaba en secreto que un barco en concreto de mi astillero fracasara en su misión. Nunca lo hizo.', 25549),
(122782, 'esES', '[%s] confiesa: Hace mucho que no visito mi ciudadela. Espero que mis seguidores estén bien.', '[%s] confiesa: Hace mucho que no visito mi ciudadela. Espero que mis seguidores estén bien.', 25549),
(122781, 'esES', '[%s] confiesa: Me gusta más el antiguo Dalaran. Ese no, el otro.', '[%s] confiesa: Me gusta más el antiguo Dalaran. Ese no, el otro.', 25549),
(122780, 'esES', '[%s] confiesa: Yo era ese que siempre activaba Aspecto de la manada.', '[%s] confiesa: Yo era esa que siempre activaba Aspecto de la manada.', 25549),
(122779, 'esES', '[%s] confiesa: Nunca presto atención cuando hablamos de cómo enfrentarnos a un nuevo jefe de banda.', '[%s] confiesa: Nunca presto atención cuando hablamos de cómo enfrentarnos a un nuevo jefe de banda.', 25549),
(122778, 'esES', '[%s] confiesa: A menudo me pregunto si las barbas de los vrykuls son más suaves que el pelaje de los gatitos.', '[%s] confiesa: A menudo me pregunto si las barbas de los vrykuls son más suaves que el pelaje de los gatitos.', 25549),
(122777, 'esES', '[%s] confiesa: Vendo todo lo que no necesito porque me da mucha pereza usar la casa de subastas.', '[%s] confiesa: Vendo todo lo que no necesito porque me da mucha pereza usar la casa de subastas.', 25549),
(122776, 'esES', '[%s] confiesa: He dedicado mucho más tiempo del que me gustaría a buscar Splashran en el mar.', '[%s] confiesa: He dedicado mucho más tiempo del que me gustaría a buscar Splashran en el mar.', 25549),
(122775, 'esES', '[%s] confiesa: No me puedo creer lo grandes que son las armas tauren.', '[%s] confiesa: No me puedo creer lo grandes que son las armas tauren.', 25549),
(122774, 'esES', '[%s] confiesa: Creía que ya habíamos derrotado a la Legión.', '[%s] confiesa: Creía que ya habíamos derrotado a la Legión.', 25549),
(122773, 'esES', '[%s] confiesa: No sé lo que es una piedra de salud y, a estas alturas, me da miedo preguntarlo.', '[%s] confiesa: No sé lo que es una piedra de salud y, a estas alturas, me da miedo preguntarlo.', 25549),
(122772, 'esES', '¡Acabad con esta farsa, demonios! ¡Sabéis que no podéis derrotarme!', '', 25549),
(122771, 'esES', '¡La Legión piensa que sus trucos nos cogen por sorpresa, pero estamos preparados!', '', 25549),
(122770, 'esES', 'Caen del cielo con mucho aplomo. Ah, dulce catarsis.', '', 25549),
(122769, 'esES', 'Creo que he perdido mi piedra de hogar de Dalaran, ¿me puedes dar otra?', 'Creo que he perdido mi piedra de hogar de Dalaran, ¿me puedes dar otra?', 25549),
(122768, 'esES', 'Tu sacrificio será recordado.', '', 25549),
(122767, 'esES', '¡Hago lo que es necesario!', '', 25549),
(122766, 'esES', 'Tu hoja es certera, Jarod. ¡Ven conmigo, pongamos fin a este ataque!', '', 25549),
(122765, 'esES', 'Solo espero que su sacrificio haya merecido la pena.', '', 25549),
(122764, 'esES', 'Este lugar se construyó para soportar cualquier ataque, pero nadie podía predecir la fuerza de la Legión.', '', 25549),
(122763, 'esES', '¡Luchas con gran poder, maestro Illidan!', '', 25549),
(122762, 'esES', 'No soy un héroe, pero será un honor luchar a tu lado.', '', 25549),
(122761, 'esES', 'Esto no me gusta demasiado, maestro Illidan.', '', 25549),
(122760, 'esES', 'Una batalla digna. Jamás habría logrado derrotar a un Señor del Terror yo solo.', '', 25549),
(122759, 'esES', '¡Illidan! Creo que hay un Señor del Terror en el mausoleo. Tu ayuda será muy útil.', '', 25549),
(122758, 'esES', '¡Que el fuego os purifique, demonios!', '', 25549),
(122757, 'esES', 'Yo me encargaré de los cielos. Parece que aún te necesitan en tierra firme.', '', 25549),
(122756, 'esES', '¡Creía que este ataque incesante no acabaría nunca!', '', 25549),
(122755, 'esES', '¡Illidan! ¡Montas ese dragón como si lo llevaras en la sangre!', '', 25549),
(122754, 'esES', 'Mi hacha es tuya.', '', 25549),
(122753, 'esES', 'Aprendo nuevas técnicas de combate solo con luchar a tu lado, Illidan.', '', 25549),
(122752, 'esES', 'Toda ayuda contra este tipo de enemigo es bien recibida.', '', 25549),
(122751, 'esES', 'Illidan, luchas con fuerza y gracia. Es un honor verte batallar.', '', 25549),
(122750, 'esES', 'Haces lo que es necesario. Es una cualidad admirable.', '', 25549),
(122749, 'esES', '¿Qué clase de magia es esa?', '', 25549),
(122748, 'esES', '¡Esta lucha no es justa! ¡Tenéis que mandar más refuerzos contra mí, demonios!', '', 25549),
(122747, 'esES', '¡Algún día te tengo que enseñar mi colección de tabardos!', '', 25549),
(122746, 'esES', '¡Algún día te tengo que enseñar mi colección de monturas!', '', 25549),
(122745, 'esES', '¡Algún día te tengo que enseñar mi colección de monedas!', '', 25549),
(122744, 'esES', '¡Algún día te tengo que enseñar mi colección de pergaminos!', '', 25549),
(122743, 'esES', '¡Algún día te tengo que enseñar mi colección de mascotas!', '', 25549),
(122742, 'esES', '¡Algún día te tengo que enseñar mi colección de jarras!', '', 25549),
(122741, 'esES', '¡Algún día te tengo que enseñar mi colección de juguetes!', '', 25549),
(122740, 'esES', 'Cuanto más bebo, mejores son mis estrategias... ¡Hip!', '', 25549),
(122739, 'esES', 'Terminé en segundo puesto en las carreras de yaks de la semana pasada. ¡Necesito un yak más rápido!', '', 25549),
(122738, 'esES', 'Todas las mañanas corro alrededor de La Isla Errante... ¡dos veces! No puedo abandonar mi entrenamiento.', '', 25549),
(122737, 'esES', '¡Algún día te tengo que enseñar mi colección de hojas!', '', 25549),
(122736, 'esES', '¡Después de esto tendré que cenar otra vez!', '¡Después de esto tendré que cenar otra vez!', 25549),
(122735, 'esES', '¡$n! ¡Tengo objetos para ti! ¡Ven a ver!', '', 25549),
(122734, 'esES', '', '¡$n! Si se me permite, tengo unas cuantas cosas guardadas que creo que podrían interesarte.', 25549),
(122733, 'esES', 'Nada raro en realidad. Energía de vez en cuando, pero nada peligroso.', 'Nada raro en realidad. Energía de vez en cuando, pero nada peligroso.', 25549),
(122732, 'esES', '', '¡$n! Si se me permite, tengo unas cuantas cosas guardadas que creo que podrían interesarte.', 25549),
(122731, 'esES', '', '¡$n! Si se me permite, tengo unas cuantas cosas guardadas que creo que podrían interesarte.', 25549),
(122730, 'esES', '', '¡$n! Si se me permite, tengo unas cuantas cosas guardadas que creo que podrían interesarte.', 25549),
(122729, 'esES', '¡$n! Si se me permite, tengo unas cuantas cosas guardadas que creo que podrían interesarte.', '', 25549),
(122728, 'esES', '', '¡$n! Si se me permite, tengo unas cuantas cosas guardadas que creo que podrían interesarte.', 25549),
(122727, 'esES', '', 'Te avisaremos si descubrimos algo.', 25549),
(122726, 'esES', '¡$n! Si se me permite, tengo unas cuantas cosas guardadas que creo que podrían interesarte.', '', 25549),
(122725, 'esES', 'No tengo tiempo para bromas, $gcazador:cazadora; de demonios.$b$bComo ya le dije al otro Illidari, estoy muy ocupado.$b$bDebo preparar la ofensiva contra la Legión mientras algunos de mis aliados claman venganza contra la Horda.', '', 25549),
(122724, 'esES', '', '¡Todo parece estar bien por aquí de momento!', 25549),
(122723, 'esES', '¡$n! Si se me permite, tengo unas cuantas cosas guardadas que creo que podrían interesarte.', '', 25549),
(122722, 'esES', '¡$GMaestro:Maestra;! Tengo buen género. Ven a echar un ojo.', '', 25549),
(122721, 'esES', '', '¡$n! Si se me permite, tengo unas cuantas cosas guardadas que creo que podrían interesarte.', 25549),
(122720, 'esES', '', 'Estás en buenas manos. ¡Te sacará de aquí en un periquete!', 25549),
(122719, 'esES', '', '¡$n! Si se me permite, tengo unas cuantas cosas guardadas que creo que podrían interesarte.', 25549),
(122718, 'esES', '', 'Parece que lo tienes casi todo bajo control.', 25549),
(122717, 'esES', '', 'Eh, Grindle... Oh, vaya. No voy ni a preguntar. Esto es cosa tuya.', 25549),
(122716, 'esES', 'Gracias a la refundación de la Mano de Plata bajo tu mandato, ahora tenemos una nueva dirección y consejo.$b$bTenemos mucho trabajo por delante.', '', 25549),
(122715, 'esES', '', '¿Qué tal van las cosas por aquí? ¿Algo fuera de lo normal?', 25549),
(122714, 'esES', '', '¿Tenéis algún problema por aquí? He oído que hay energía inestable en la zona.', 25549),
(122713, 'esES', 'Vuelve a hablarme de Khadgar.', 'Vuelve a hablarme de Khadgar.', 25549),
(122712, 'esES', 'Vuelve a hablarme de Gul''dan.', 'Vuelve a hablarme de Gul''dan.', 25549),
(122711, 'esES', 'Vuelve a hablarme de Illidan.', 'Vuelve a hablarme de Illidan.', 25549),
(122710, 'esES', 'El Kirin Tor agradece tu ayuda.', '', 25549),
(122709, 'esES', 'Debemos reclamar nuestra sagrada tierra natal.', '', 25549),
(122708, 'esES', '', '¿Tienes el valor suficiente para ayudarnos a derrotar a la Legión?', 25549),
(122707, 'esES', '¿Sientes la vida de este bosque? Hemos protegido estas tierras durante años. Pero ya no podemos seguir haciéndolo por nuestra cuenta. ¿Nos ayudarás?', '¿Sientes la vida de este bosque? Hemos protegido estas tierras durante años. Pero ya no podemos seguir haciéndolo por nuestra cuenta. ¿Nos ayudarás?', 25549),
(122706, 'esES', '', 'Atención, $n.$b$bDubin quizás sea un enano terco, pero estamos de acuerdo en una cosa: aquí pasa algo raro.', 25549),
(122705, 'esES', '', 'Debemos resistir un poco más.', 25549),
(122704, 'esES', '', 'El Consejo tiene un plan. ¡Estoy segura!', 25549),
(122703, 'esES', '', '¡Van a trasladar la ciudad pronto! ¡Es imposible seguir así!', 25549),
(122702, 'esES', '', '¡No podemos seguir así toda la vida! ¡Pronto nos arrollarán!', 25549),
(122701, 'esES', '', '¡No se acaba nunca! ¡No dejan de venir!', 25549),
(122700, 'esES', '', '¡No podremos aguantar mucho más!', 25549),
(122699, 'esES', '¡Sigues con vida! Tus campeones acudieron a mí al no lograr despertarte en tu sede de clase. Te trajimos a la enfermería. ¿Qué ha ocurrido?', '', 25549),
(122698, 'esES', '', '¡Saludos! ¿Acabas de llegar a la ciudad? No parece que sufras ningún efecto secundario.', 25549),
(122697, 'esES', '', 'Saludos, $n. ¿Te encuentras bien? Mucha gente sufre náuseas o mareos.', 25549),
(122696, 'esES', '', 'El dolor remitirá. Ahora llevas mi marca y, a través de ella, podré ver y sentir lo mismo que tú. Regresa cuando puedas, tenemos mucho que hacer.', 25549),
(122695, 'esES', '¡Jajajajajaja!', '', 25549),
(122694, 'esES', '¡Mira quién ha vuelto del mundo de los muertos! Colega, has estado inconsciente tres días. Khadgar se alegrará de que hayas despertado. Yo, por otra parte, sigo siendo un maldito león marino.', '', 25549),
(122693, 'esES', '¡No puedes ocultar tu naturaleza, demonio!', '¡No puedes ocultar tu naturaleza, demonio!', 25549),
(122692, 'esES', 'Nuestro viaje a Ulduar ha sido muy movido, pero tenemos muchas cosas que hacer.', '', 25549),
(122691, 'esES', 'Entra tú. Yo iré enseguida. Solo necesito... aclarar las ideas.', '', 25549),
(122690, 'esES', 'He cambiado de opinión. Enséñame otra vez los artefactos disponibles.', 'He cambiado de opinión. Enséñame otra vez los artefactos disponibles.', 25549),
(122686, 'esES', '¡Nadie podrá hacer frente al Martillo Crepuscular!', '¡Nadie podrá hacer frente al Martillo Crepuscular!', 25549),
(122685, 'esES', '¡Somos los heraldos de la destrucción!', '¡Somos los heraldos de la destrucción!', 25549),
(122684, 'esES', 'Pide ayuda... ¡Nadie te responderá!', 'Pide ayuda... ¡Nadie te responderá!', 25549),
(122683, 'esES', '¡El crepúsculo os acecha!', '¡El crepúsculo os acecha!', 25549),
(122682, 'esES', '¡Soy tu destrucción!', '¡Soy tu destrucción!', 25549),
(122681, 'esES', '', '¡No sé qué les pasa a las flores! Dejé de intentar recogerlas cuando... ¡cuando empezaron a recogerse a sí mismas!$b$bRaro, ¿verdad?', 25549),
(122680, 'esES', '¿Que ocurre con el viejo Fillmaff?', '¿Que ocurre con el viejo Fillmaff?', 25549),
(122679, 'esES', 'Los años pasaron y trasladamos toda la ciudad hasta Corona de Hielo por la campaña de Rasganorte.$b$bUn día, de repente, el viejo Fillmaff se dirigió a la Torre Violeta ¡y se metió dentro! No dijo ni mu. Empezó a clasificar los libros y a organizar papeles, como si no hubiera ocurrido nada. Desde entonces está así.$b$b<Varenthas se inclina hacia ti y susurra:>$b$bCreo que no sabe que está muerto.', '', 25549),
(122678, 'esES', '¿Fillmaff? ¿Ese vejestorio? Ha trabajado como archivista aquí, en Dalaran, durante décadas. Aún lo recuerdo de mi época de estudiante, cuando se le iban las horas entre libros. Sabía cómo encontrar cualquier cosa.$b$bLuego estalló la Tercera Guerra y Arthas saqueó la ciudad. Fillmaff desapareció junto a muchos otros. Fue uno más de tantos muertos como hubo. Nadie reparó en ello.', '', 25549),
(122677, 'esES', '¿Entonces ese eredar, Balaadur, le tendió una emboscada a Arrexis? Seguro que tiene el bastón...\n\nCon la invasión, seguro que está aquí o nos está observando. Se me ocurre algo... atrevido.\n\n¡Recreemos el ritual de Arrexis! Si realizamos el ritual en un punto de invasión, atraeremos la atención de Balaadur. Seguro que intenta una emboscada, pero estaremos preparados.', '', 25549),
(122676, 'esES', '<Sin decir nada, te mira con recelo.>', '<Sin decir nada, te mira con recelo.>', 25549),
(122675, 'esES', 'Si tú lo dices.', 'Si tú lo dices.', 25549),
(122674, 'esES', 'No me das miedo.', 'No me das miedo.', 25549),
(122673, 'esES', 'Pues lucha contra mí.', 'Pues lucha contra mí.', 25549),
(122672, 'esES', 'No tengo.', 'No tengo.', 25549),
(122671, 'esES', 'Vete.', 'Vete.', 25549),
(122670, 'esES', '¿Qué?', '¿Qué?', 25549),
(122669, 'esES', 'Je.', 'Je.', 25549),
(122668, 'esES', 'Déjame en paz.', 'Déjame en paz.', 25549),
(122667, 'esES', 'Conozco tu secreto.', 'Conozco tu secreto.', 25549),
(122666, 'esES', '|TInterface\\Icons\\sha_ability_rogue_envelopingshadows_nightmare:20|t¡Il''gynoth está a punto de terminar su |cFFFF0000|Hspell:223121|h[Letargo final]|h|r!', '|TInterface\\Icons\\sha_ability_rogue_envelopingshadows_nightmare:20|t¡Il''gynoth está a punto de terminar su |cFFFF0000|Hspell:223121|h[Letargo final]|h|r!', 25549),
(122665, 'esES', 'Si pretendes blandir las armas del Señor del Trueno, entra y descubre sus hazañas y la causa de su caída…', '', 25549),
(122664, 'esES', '¡He formulado una pregunta! ¡Responde!', '¡He formulado una pregunta! ¡Responde!', 25549),
(122663, 'esES', '¡Hola, $gamigo:amiga;! En realidad no soy yo, Khadgar, sino solo mi aspecto de tipo duro y atractivo y mis vastos conocimientos. Si deseas la solución a cualquier pregunta, tan solo has de preguntar y solicitar la respuesta.\n\nMi amplitud mental es tal que solo quedaba espacio mágico para ofrecer unas cuantas frases de respuesta en este dispositivo, así que asegúrate de formular cuestiones MUY ESPECÍFICAS.', '', 25549),
(122662, 'esES', 'Esto no puede esperar. Hay demonios en tus filas. Te lo voy a enseñar.', 'Esto no puede esperar. Hay demonios en tus filas. Te lo voy a enseñar.', 25549),
(122661, 'esES', '<Al parecer, Arduen estaba prisionero. Su cara es de un blanco fantasmal.>$b$bLogré... escapar... y corrí...$b$bCasi... lo consigo...$b$bPor favor, $n, salva... a los demás... Illidari...', '', 25549),
(122660, 'esES', 'Ulduar guarda muchos secretos.', '', 25549),
(122659, 'esES', '', 'Buena suerte para todos.', 25549),
(122658, 'esES', '', 'XXXX', 25549),
(122657, 'esES', '¡Avanza cuando las ánimas de maná estén distraídas!', '¡Avanza cuando las ánimas de maná estén distraídas!', 25549),
(122656, 'esES', '', 'No te preocupes, mortal. Tu consciencia se ha proyectado hasta mi presencia astral en la Gran Oscuridad del Más Allá.', 25549),
(122655, 'esES', '', 'Soy Xe''ra, uno de los primeros naaru. Me forjaron aquí durante la gran ordenación del cosmos.', 25549),
(122654, 'esES', '¡Partiremos en cuanto digas!', '', 25549),
(122653, 'esES', 'Partiremos rumbo al Templo de la Luz Abisal de inmediato.', '', 25549),
(122652, 'esES', 'He vuelto a Dalaran en cuanto me he enterado de que la profecía se había cumplido.\n\nHas unido a todos bajo la Luz, tal y como predije. Esperemos que tu esfuerzo nos brinde la fuerza que necesitamos para derrotar a Balnazzar de una vez por todas.', '', 25549),
(122651, 'esES', '<Sirius Alabenuz está tan blanco como un fantasma. Tiembla descontroladamente.>', '', 25549),
(122650, 'esES', '<El cuerpo de Cassiel Nochespina está casi irreconocible. Lo torturaron y después murió a causa de las heridas.>', '', 25549),
(122649, 'esES', '', '$n, eres tú.\n\nSeguíamos a un peligroso Señor del Terror. Por desgracia, nos llevó directamente a una trampa.', 25549),
(122648, 'esES', '¡Este demonio lucha con ganas!', '¡Este demonio lucha con ganas!', 25549),
(122647, 'esES', 'No tenemos el poder...', 'No tenemos el poder...', 25549),
(122646, 'esES', '¡Es demasiado fuerte! ¡Qué locura!', '¡Es demasiado fuerte! ¡Qué locura!', 25549),
(122645, 'esES', '', 'Su nombre es Illidan Tempestira.', 25549),
(122644, 'esES', '', 'He venido aquí en busca del hijo de la Luz y la Sombra. El chico destinado a poner fin a la era de los demonios.', 25549),
(122643, 'esES', '', 'Pero ahora, el Ejército Dorado está al borde del olvido. Su campaña en Argus pronto verá un final sangriento. Si caen, la Legión iniciará una nueva Cruzada Ardiente, y el cosmos temblará ante su llegada.', 25549),
(122642, 'esES', '', 'De las cenizas de esos mundos asolados se alzaron los supervivientes para hacer frente a los demonios. Formaron el Ejército de la Luz.', 25549),
(122641, 'esES', '', 'Tras la caída, no quedó nadie para oponerse a la voluntad de Sargeras. Libre, partió junto a su Legión Ardiente y aniquiló innumerables mundos en la Cruzada Ardiente.', 25549),
(122640, 'esES', '', 'En un tiempo muy lejano, se luchó una gran batalla que determinó el destino de todos los mundos. En esa batalla decisiva, el Panteón todopoderoso cayó frente al Titán Oscuro, Sargeras.', 25549),
(122639, 'esES', '', 'Has venido al crisol de la creación en busca de respuestas. Escucha y comprenderás.', 25549),
(122638, 'esES', 'Descansa en paz, camarada.', 'Descansa en paz, camarada.', 25549),
(122637, 'esES', 'La Pesadilla no tiene cabida aquí y tenemos que hacer todo lo posible para proteger a Malorne. Sin él, el propio equilibrio de la naturaleza queda expuesto.$b$bMe temo que nuestra prioridad absoluta es salvarlo... aunque nos vaya la vida en ello.', '', 25549),
(122636, 'esES', '', 'Debe de ser complicado para los dioses salvajes tener que revivir este momento. Aquella invasión de la Legión tuvo que ser algo terrorífico.', 25549),
(122635, 'esES', '', '¡No me gusta nada este lugar! ¡Deshagámonos de estos monstruos invasores!', 25549),
(122634, 'esES', '', 'Loh enemigoh y la Pesadilla son muy lihtoh. Eligieron el momento en que loh dioses salvajes cayeron en batalla hace mileh de añoh, cuando salieron en defensa de Azeroth contra la Legión Ardiente.', 25549),
(122633, 'esES', 'Sirius, ¿estás bien?', 'Sirius, ¿estás bien?', 25549),
(122632, 'esES', 'Asha, eres libre.', 'Asha, eres libre.', 25549),
(122631, 'esES', 'Jagganoth me... vengará...', '', 25549),
(122630, 'esES', '¡AL LADRÓN!', '', 25549),
(122629, 'esES', 'Cuídate, $c...', '', 25549),
(122628, 'esES', '', 'Les dije que pasaría esto.\n\nSe lo DIJE.\n\n¿Y me hicieron caso?', 25549),
(122627, 'esES', 'Dime, $c, ¿ya has explorado las maravillas ocultas de Dalaran? Si no encuentras lo que buscas, seguro que conozco a alguien que podrá ayudarte.', '', 25549),
(122626, 'esES', '', '¡Anda y vete a tomar viento!', 25549),
(122625, 'esES', '', 'Sé queeeee estás con la Leeeegión. Así eres tú. Así hablas.', 25549),
(122624, 'esES', 'Hola, $gciudadano:ciudadana;. ¿Cuál es el problema?', '', 25549),
(122623, 'esES', 'Larry te va a convertir en una suculenta salsa boloñesa.', '', 25549),
(122622, 'esES', 'Je, este ya está listo.', '', 25549),
(122621, 'esES', '¡Por la gloria!', '¡Por la gloria!', 25549),
(122620, 'esES', 'Temerán nuestra cólera.', 'Temerán nuestra cólera.', 25549),
(122619, 'esES', '¡Mi vida por Odyn!', '¡Mi vida por Odyn!', 25549),
(122618, 'esES', 'Val''sharah', 'Val''sharah', 25549),
(122617, 'esES', 'Mi lanza es tuya.', 'Mi lanza es tuya.', 25549),
(122616, 'esES', '¡Val''kyr, ha llegado nuestro momento! ¡A luchar!', '¡Val''kyr, ha llegado nuestro momento! ¡A luchar!', 25549),
(122615, 'esES', '¡Val''kyr! ¡Se ha lanzado la llamada! ¡Preparaos!', '¡Val''kyr! ¡Se ha lanzado la llamada! ¡Preparaos!', 25549),
(122614, 'esES', 'Monte Alto', 'Monte Alto', 25549),
(122613, 'esES', 'Azsuna', 'Azsuna', 25549),
(122612, 'esES', '¿Puedes conseguirme un vuelo para salir de aquí?', '¿Puedes conseguirme un vuelo para salir de aquí?', 25549),
(122611, 'esES', 'Creo que un $c te estaba buscando en la ciudad, dijo algo de un arma antigua. Deberías hablar con él antes de adentrarte en las Islas Abruptas. Vas a necesitar toda la ayuda posible.\n\nQuiero decir... que puedo conseguirte un vuelo si realmente lo quieres. Pero no te lo recomiendo.', '', 25549),
(122610, 'esES', 'Creo que nuestras heridas se han curado lo suficiente. Seguiré explorando. Cuídate, Lilryia.', '', 25549),
(122609, 'esES', '', '¡Argh! ¡Me estás haciendo enfadar!', 25549),
(122608, 'esES', '', '¿Por qué luchamos?', 25549),
(122607, 'esES', 'Hemos tenido suerte de haber recibido el aviso de Malorne, por muy terrible que sea. Siento un gran temor por el Sueño Esmeralda. Si se corrompe, las consecuencias sobre Azeroth serán espantosas.', '', 25549),
(122606, 'esES', '', '¡Buen combate! Los enemigos de los Vigías de la noche pagan cara su traición.', 25549),
(122605, 'esES', 'Todo dispuesto para asaltar Hrydshal.', 'Todo dispuesto para asaltar Hrydshal.', 25549),
(122604, 'esES', '', 'Los magos más poderosos de este templo conspiran contra los Vigías de la noche. ¡Enseñadles cómo tratamos al enemigo!', 25549),
(122603, 'esES', '', 'Hasta los espíritus reaccionan ante la fuerza. ¡Bien hecho!', 25549),
(122602, 'esES', '', 'El Templo de las Mil Luces está lleno de espíritus enloquecidos. Hay que recordarles cómo comportarse.', 25549),
(122601, 'esES', '<Activa el módulo con 25 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná antiguo.>', '<Activa el módulo con 25 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná antiguo.>', 25549),
(122600, 'esES', 'Este módulo parece haber perdido su fuente de energía hace mucho tiempo.', '', 25549),
(122599, 'esES', 'Si necesitas un vuelo a Dalaran, mis murciélagos están listos.', '', 25549),
(122598, 'esES', 'Pero ¿qué dingue?', '', 25549),
(122597, 'esES', 'Los Señores del Agua de Hydraxis están contigo. ¡La Legión Ardiente no vencerá!', '', 25549),
(122596, 'esES', 'Oyes un rugido extraño en la cueva de más adelante.', 'Oyes un rugido extraño en la cueva de más adelante.', 25549),
(122595, 'esES', 'Será un honor para mí.', 'Será un honor para mí.', 25549),
(122594, 'esES', 'Mi escudo es tuyo.', 'Mi escudo es tuyo.', 25549),
(122593, 'esES', 'Serviré como protector.', 'Serviré como protectora.', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(122592, 'esES', 'Oyes un extraño crujido en los portales de abajo.', 'Oyes un extraño crujido en los portales de abajo.', 25549),
(122591, 'esES', '', 'Los Descoronados son un medio para lograr un fin. El fin de la Legión.', 25549),
(122590, 'esES', 'Cuernoatroz', 'Cuernoatroz', 25549),
(122589, 'esES', 'Hidra', 'Hidra', 25549),
(122588, 'esES', 'Bestia fluvial', 'Bestia fluvial', 25549),
(122587, 'esES', 'Rylak', 'Rylak', 25549),
(122586, 'esES', 'Máquina', 'Máquina', 25549),
(122585, 'esES', 'Estoy listo para buscar la última hoja.', 'Estoy lista para buscar la última hoja.', 25549),
(122584, 'esES', '', 'Tranquilízate, pronto nos iremos a casa.', 25549),
(122583, 'esES', '', 'Si lo rompes, madre tendrá que comprarlo.', 25549),
(122582, 'esES', '', 'Acuérdate: los cristales no se tocan.', 25549),
(122581, 'esES', '', 'No des mucho jaleo y deja que madre mire lo que hay.', 25549),
(122580, 'esES', '', '¡Esas manos, criaturita!', 25549),
(122579, 'esES', '', 'Más vale que no rompas nada.', 25549),
(122578, 'esES', 'Quisiera revisar la información que tenemos sobre el artefacto restante.', 'Quisiera revisar la información que tenemos sobre el artefacto restante.', 25549),
(122577, 'esES', 'El núcleo de falla está cargado. Coloca el cañón de falla según consideres.', 'El núcleo de falla está cargado. Coloca el cañón de falla según consideres.', 25549),
(122576, 'esES', 'Ya se ha dado la orden. Comenzaremos a cargar el núcleo de falla de inmediato.', 'Ya se ha dado la orden. Comenzaremos a cargar el núcleo de falla de inmediato.', 25549),
(122575, 'esES', 'Mimiron me dio una plataforma de teletransporte para usar en caso de emergencia. ¡Diría que esta es una!', '', 25549),
(122574, 'esES', 'Tengo muchas ganas de volver a ver a Magni. Ha pasado mucho tiempo.', '', 25549),
(122573, 'esES', 'Los que me invocan pagan el precio: ¡Entregadme vuestra alma eterna!', '', 25549),
(122572, 'esES', '¿Queréis un pasaje a Helheim? ¡Entonces lo tendréis!', '', 25549),
(122571, 'esES', '¡Todos los que invocan al barquero deben pagar el precio!', '', 25549),
(122570, 'esES', '¡Espíritus! ¡Arrojad a estos mortales a la marea!', '', 25549),
(122569, 'esES', 'Venado', 'Venado', 25549),
(122568, 'esES', 'Esta acción cuesta 50 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná antiguo. ¿Quieres continuar?', 'Esta acción cuesta 50 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná antiguo. ¿Quieres continuar?', 25549),
(122567, 'esES', '<Libera al sable de maná de vínculo vil por 50 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná antiguo.>', '<Libera al sable de maná de vínculo vil por 50 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná antiguo.>', 25549),
(122566, 'esES', '¡La Luz te consumirá!', '', 25549),
(122565, 'esES', '¿Sabes que soy rey, verdad?', '', 25549),
(122564, 'esES', 'Suramar se alza.', 'Suramar se alza.', 25549),
(122563, 'esES', '<La Legión ha encarcelado a este sable de maná, pero puedes liberarlo si sobrecargas el cristal con maná antiguo.>', '', 25549),
(122562, 'esES', 'Pones a prueba mi paciencia.', '', 25549),
(122561, 'esES', 'No es el momento.', '', 25549),
(122560, 'esES', 'La Luz lleva a la victoria.', '', 25549),
(122559, 'esES', 'Que tengas un buen viaje.', '', 25549),
(122558, 'esES', 'Nunca pierdas la esperanza.', '', 25549),
(122557, 'esES', 'Siempre tendrás las puertas de Ventormenta abiertas.', '', 25549),
(122556, 'esES', 'No bajes la guardia.', '', 25549),
(122555, 'esES', 'Un rey es tan noble como las causas que defiende.', '', 25549),
(122554, 'esES', 'Por la Alianza, por encima de todo.', '', 25549),
(122553, 'esES', 'Siempre merece la pena luchar por una causa justa.', '', 25549),
(122552, 'esES', 'A veces debemos luchar por lo que creemos.', '', 25549),
(122551, 'esES', 'Buenas.', '', 25549),
(122550, 'esES', 'Ventormenta resistirá.', '', 25549),
(122549, 'esES', 'Ventormenta agradece tu servicio a la Alianza.', '', 25549),
(122548, 'esES', '¡La Legión Ardiente temblará ante el poder de los Cuatro Jinetes!', '', 25549),
(122547, 'esES', '¡Jinetes! ¡Nuestro destino está próximo!', '', 25549),
(122546, 'esES', '¡NO! ¡No permitiré que caiga la Espada de Ébano!', '', 25549),
(122545, 'esES', '¡Soy demasiado rico para morir así!', '¡Soy demasiado rica para morir así!', 25549),
(122544, 'esES', 'Guardias, ¿para qué os pagamos? ¡Matad a esta bestia!', 'Guardias, ¿para qué os pagamos? ¡Matad a esta bestia!', 25549),
(122543, 'esES', '¡Su''esh está suelto! ¡Corred!', '¡Su''esh está suelto! ¡Corred!', 25549),
(122542, 'esES', '¡Vamos a morir!', '¡Vamos a morir!', 25549),
(122541, 'esES', '¡Quieres luchar por mi isla! ¡Bien! ¡La pintaré con tu sangre!', '', 25549),
(122540, 'esES', '', 'Lucharé con honor por la Orden de la Mano de Plata.', 25549),
(122539, 'esES', '¿¡Qué!?', '¿¡Qué!?', 25549),
(122538, 'esES', '¡Ja! ¡¿Dónde están ahora tus malignos de maná?!', '¡Ja! ¡¿Dónde están ahora tus malignos de maná?!', 25549),
(122537, 'esES', '¿Hay que limpiar algo?', '', 25549),
(122536, 'esES', 'No hay tiempo para hablar. Hay que limpiar.', '', 25549),
(122535, 'esES', 'Ocupado, muy ocupado. D-debo volver al trabajo.', '', 25549),
(122534, 'esES', 'Estoy listo. ¡A Ulduar!', 'Estoy lista. ¡A Ulduar!', 25549),
(122533, 'esES', '¡Será mejor que nos movamos!', '', 25549),
(122532, 'esES', '¡¡NO VAIS A CONQUISTAR MI ISLA!!', '', 25549),
(122531, 'esES', 'Una tarea desagradable, pero necesaria. Prepararé las Lágrimas de Elune para el transporte. Reúnete conmigo en La Ciudadela Violeta.', '', 25549),
(122530, 'esES', '¡BÚSCATE TU PROPIA ISLA!', '', 25549),
(122529, 'esES', '¡ESTA ES MI ISLA!', '', 25549),
(122528, 'esES', 'Los guardias te olfatean y gruñen por lo bajo.', '', 25549),
(122527, 'esES', 'Con gusto.', 'Con gusto.', 25549),
(122526, 'esES', '¡Maravilloso! Es fantástico ver que alguien joven como tú se interesa por la historia. Al final, se podría decir que lo que dejamos atrás es lo que importa.\n\nTengo algo por aquí... Es un libro de un género completamente distinto, que podría ofrecerte a cambio de lo mucho que te has esforzado. ¿Lo quieres?', '', 25549),
(122525, 'esES', 'Ya he conseguido todos los volúmenes.', 'Ya he conseguido todos los volúmenes.', 25549),
(122524, 'esES', '¡Te he estado buscando por todas partes! ¿Lo de la cabeza en la bola de cristal? Estoy probando algo nuevo.', '', 25549),
(122523, 'esES', '<Le ha ocurrido algo terrible a este vagabundo solitario.>\n\n<Lamentablemente, no hay manera de liberarlo.>', '', 25549),
(122522, 'esES', '<Le ha ocurrido algo terrible a este vagabundo solitario.>', '', 25549),
(122521, 'esES', 'Recluta a templarios de la Mano de Plata.', 'Recluta a templarios de la Mano de Plata.', 25549),
(122520, 'esES', 'Recluta a caballeros de la Mano de Plata.', 'Recluta a caballeros de la Mano de Plata.', 25549),
(122519, 'esES', '¿En qué puedo ayudarte hoy?', '¿En qué puedo ayudarte hoy?', 25549),
(122518, 'esES', 'Gamer timer', 'Gamer timer', 25549),
(122517, 'esES', 'Fin de la ronda.', 'Fin de la ronda.', 25549),
(122516, 'esES', 'Nivel 4 defendido', 'Nivel 4 defendido', 25549),
(122515, 'esES', 'Nivel 3 defendido', 'Nivel 3 defendido', 25549),
(122514, 'esES', 'Nivel 2 defendido', 'Nivel 2 defendido', 25549),
(122513, 'esES', '<Imbuye uno de los tridentes de 25 p. |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t de maná antiguo.>', '<Imbuye uno de los tridentes de 25 p. |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t de maná antiguo.>', 25549),
(122512, 'esES', 'Nivel 1 defendido', 'Nivel 1 defendido', 25549),
(122511, 'esES', 'Essstasss armasss mundanasss encierran un potencial oculto.', '', 25549),
(122510, 'esES', 'Oyes un chillido salvaje que viene del portal de las Tierras del Interior.', 'Oyes un chillido salvaje que viene del portal de las Tierras del Interior.', 25549),
(122509, 'esES', 'Oyes un chillido salvaje que viene del portal de Feralas.', 'Oyes un chillido salvaje que viene del portal de Feralas.', 25549),
(122508, 'esES', 'Oyes un chillido salvaje que viene del portal del Bosque del Ocaso.', 'Oyes un chillido salvaje que viene del portal del Bosque del Ocaso.', 25549),
(122507, 'esES', '', 'Si quieres algo bien hecho, tienes que matarlo tú misma...', 25549),
(122506, 'esES', '', '¡Permíteme que te muestre el poder de la Legión!', 25549),
(122505, 'esES', 'Mi vida por la Luz.', 'Mi vida por la Luz.', 25549),
(122504, 'esES', 'Lucharé por ti.', 'Lucharé por ti.', 25549),
(122503, 'esES', 'Oyes cómo algo sale a toda prisa detrás de ti... y luego silencio.', 'Oyes cómo algo sale a toda prisa detrás de ti... y luego silencio.', 25549),
(122502, 'esES', 'Buen asalto...', '', 25549),
(122501, 'esES', 'Mal... ditos...', '', 25549),
(122500, 'esES', 'Serás un buen calentamiento para mi entrenamiento real.', '', 25549),
(122499, 'esES', 'Soy el hijo del maestro. No das la talla.', '', 25549),
(122498, 'esES', 'Ayudemos a los aliados de la Luz y defendamos el Templo de la Luz Abisal. ¡Al portal!', '', 25549),
(122497, 'esES', 'Estamos armados y listos para luchar. ¡Cuando ordenes!', '', 25549),
(122496, 'esES', 'La Legión Ardiente ha iniciado el ataque. ¡Debemos defender el Templo de la Luz Abisal!', 'La Legión Ardiente ha iniciado el ataque. ¡Debemos defender el Templo de la Luz Abisal!', 25549),
(122495, 'esES', 'Parece que hemos llegado justo a tiempo.', '', 25549),
(122494, 'esES', '¡Explosiones! ¡MÁS explosiones! ¡Tengo que provocar más explosiones!', '', 25549),
(122493, 'esES', '¡Usurpadores! ¡Gnomeregan es mía!', '', 25549),
(122492, 'esES', '¡Jinetes, nuestra hora ha llegado!', '', 25549),
(122491, 'esES', 'Me reuniré contigo en el nivel superior cuando lo tengas todo a punto.', '', 25549),
(122490, 'esES', 'Ha llegado la hora de que ocupe mi puesto como líder de los Cuatro Jinetes.', '', 25549),
(122489, 'esES', 'Los Cicatriz del Terror están bajo tu mando, $gSeñor supremo:Señora suprema;.\n\nQue los mundos de tus enemigos caigan rendidos a tus pies.', '', 25549),
(122488, 'esES', '', '¡Cortesanos! ¡Defendednos mientras seguimos con el ritual!', 25549),
(122487, 'esES', '¡No temáis, absorberé el poder de la Fuente de la Noche para acabar con ellos!', '', 25549),
(122486, 'esES', '¡Intrusos!', '', 25549),
(122485, 'esES', 'La intrusión no ha pasado desapercibida, pero el ritual continúa.', 'La intrusión no ha pasado desapercibida, pero el ritual continúa.', 25549),
(122484, 'esES', '¡|TInterface\\Icons\\ability_priest_shadowyapparition:20|t%s ha invocado una |cFFFF0000|Hspell:226089|h[Imagen de sombra]|h|r! ¡Destiérrala!', '¡|TInterface\\Icons\\ability_priest_shadowyapparition:20|t%s ha invocado una |cFFFF0000|Hspell:226089|h[Imagen de sombra]|h|r! ¡Destiérrala!', 25549),
(122483, 'esES', '¡Todo listo!', '¡Todo listo!', 25549),
(122482, 'esES', 'Ven a la Semilla de los Tiempos, Archidruida. Allí desvelaremos más misterios sobre tu arma.', '', 25549),
(122481, 'esES', '¡La Pesadilla empieza a apoderarse de ti!', '¡La Pesadilla empieza a apoderarse de ti!', 25549),
(122480, 'esES', '¡Es la hora! ¡Vanguardia de la Mano de Plata, a luchar!', '¡Es la hora! ¡Vanguardia de la Mano de Plata, a luchar!', 25549),
(122479, 'esES', '¡Por el honor y la gloria!', '¡Por el honor y la gloria!', 25549),
(122478, 'esES', 'Sí, llévame de vuelta. Tengo cosas que hacer.', 'Sí, llévame de vuelta. Tengo cosas que hacer.', 25549),
(122477, 'esES', 'Esta misión es muy importante, pero, si necesitas hacer más preparativos, puedo devolverte a El Eterium. ¿Quieres que lo haga?', 'Esta misión es muy importante, pero, si necesitas hacer más preparativos, puedo devolverte a El Eterium. ¿Quieres que lo haga?', 25549),
(122476, 'esES', 'Aún no estoy listo.', 'Aún no estoy lista.', 25549),
(122475, 'esES', '<La magia zumba en el portal.>', '', 25549),
(122474, 'esES', 'Descifrando.', 'Descifrando.', 25549),
(122473, 'esES', 'Me pongo al servicio de tu causa.', 'Me pongo al servicio de tu causa.', 25549),
(122472, 'esES', '¡Paladines de la Mano de Plata! ¡Aprestaos para la batalla!', '¡Paladines de la Mano de Plata! ¡Aprestaos para la batalla!', 25549),
(122471, 'esES', 'Ven. Reúnete conmigo en la Forja del Guardián.', '', 25549),
(122470, 'esES', '¿Qué clase de ente vil nos envían estos demonios? ¡Madre Luna, ayúdanos!', '', 25549),
(122469, 'esES', 'Reúnete conmigo en Dalaran, sobre el Paso de la Muerte. Tengo un plan. ¡Es muy peligroso... pero es mejor que nada!', '', 25549),
(122468, 'esES', 'Necesitamos los Pilares de la Creación para enviar a los demonios al Vacío Abisal y salvar nuestro mundo.', '', 25549),
(122467, 'esES', '¡Dalaran está asediada! ¡La Legión pretende hacernos caer de los cielos!', '', 25549),
(122466, 'esES', '', 'Lleva tu tabardo con orgullo, $n. El rojo disimulará tus heridas ante tus enemigos.', 25549),
(122465, 'esES', '¡Ah! He pronunciado siete palabras. Es mi límite.', '', 25549),
(122464, 'esES', 'Háblame de tus postes.', 'Háblame de tus postes.', 25549),
(122463, 'esES', 'Necesitamos descansar, maestro.', 'Necesitamos descansar, maestro.', 25549),
(122462, 'esES', '¡Guardia Lunar, canalizad vuestra energía hacia mí! ¡Que estos monstruos sientan el poder de lo Arcano!', '', 25549),
(122461, 'esES', '¡Detrás de ti! ¡Se ha abierto otra puerta vil!', '', 25549),
(122460, 'esES', 'Ese es el problema de la magia, ¡nunca sabes cuándo se volverá en tu contra!', '', 25549),
(122459, 'esES', 'Siempre he odiado a los elementales de agua... ¡Sobre todo a los grandes como este!', '', 25549),
(122458, 'esES', '¡La pesca puede esperar! ¡Ayúdame a aniquilar a este elemental! ', '', 25549),
(122457, 'esES', '¿Vas a golpear primero o te quedarás mirando cual cobarde llorica?', '', 25549),
(122456, 'esES', '', 'Ven para acá, $gforastero asqueroso:forastera asquerosa;. Te voy a dejar la iniciativa y todo. Que no se diga.', 25549),
(122455, 'esES', 'Pide una bendición.', 'Pide una bendición.', 25549),
(122454, 'esES', '', 'La orden está contigo.', 25549),
(122453, 'esES', '', 'Elisande pagará por su traición.', 25549),
(122452, 'esES', '¡Hemos destruido la puerta de la prisión! ¡Tenemos vía libre a Dalaran!', '', 25549),
(122451, 'esES', 'Debieron hacerme caso desde el principio y destruir a todos los sátiros antes de que pasara esto.\n\nGracias por liberarme de la locura de Xavius.', '', 25549),
(122450, 'esES', '', 'El poder de la Fuente de la Noche me llama.', 25549),
(122449, 'esES', '', 'Qué ganas tenía de volver a casa...', 25549),
(122448, 'esES', '<Usa 25 p. |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t de maná antiguo para extraer una fracción de energía Ley.>', '<Usa 25 p. |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t de maná antiguo para extraer una fracción de energía Ley.>', 25549),
(122447, 'esES', 'Avancemos, no hay tiempo que perder.', '', 25549),
(122446, 'esES', 'El resguardo palpita con energía rebosante.', '', 25549),
(122445, 'esES', 'La Legión caerá hoy.', '', 25549),
(122444, 'esES', 'Tenemos que detener a Gul''dan antes de que complete el ritual.', '', 25549),
(122443, 'esES', 'La señora Goya se llevó la mercancía y me dejó a cargo del local. Dijo algo de una ciudad en el cielo. ¡Ja! ¡Las ciudades no vuelan!', '', 25549),
(122441, 'esES', '¿Puede el poder de la esencia de claridad guiarnos al corazón de la Pesadilla?', '¿Puede el poder de la esencia de claridad guiarnos al corazón de la Pesadilla?', 25549),
(122440, 'esES', 'Estoy listo para comenzar La defensa del Templo de la Luz Abisal.', 'Estoy lista para comenzar La defensa del Templo de la Luz Abisal.', 25549),
(122439, 'esES', 'No podemos esperar más tiempo. Debemos enfrentarnos a la Legión cara a cara.', '', 25549),
(122438, 'esES', 'Deberíamos continuar nuestra patrulla. No sabemos cuántas incursiones más nos esperan.', '', 25549),
(122437, 'esES', 'Esperaba más de estos demonios. Quizás podamos encontrar a un señor del foso. Siempre he querido encadenar la esencia de un señor del foso.', '', 25549),
(122436, 'esES', 'El ritual ha sido interrumpido. La figura suspendida en la Fuente de la Noche despierta.', 'El ritual ha sido interrumpido. La figura suspendida en la Fuente de la Noche despierta.', 25549),
(122435, 'esES', 'Oyes el canto sostenido y el ritmo de un ritual complejo dentro de la aguja.', 'Oyes el canto sostenido y el ritmo de un ritual complejo dentro de la aguja.', 25549),
(122434, 'esES', 'Los guardianes de la Pesadilla han caído. ¿Qué más hay que hacer para llegar hasta Xavius?', 'Los guardianes de la Pesadilla han caído. ¿Qué más hay que hacer para llegar hasta Xavius?', 25549),
(122433, 'esES', '¡Lo habéis conseguido, campeones! El Iris está desbloqueado. Lo abriré cuando me digáis.', '', 25549),
(122432, 'esES', '<Haz una ofrenda de 20 p. |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t de maná antiguo.>', '<Haz una ofrenda de 20 p. |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t de maná antiguo.>', 25549),
(122431, 'esES', 'Cinere, hijo de Exurotus, la nueva furia de Fuego Glacial, desea otorgarte su favor.', '', 25549),
(122430, 'esES', 'Te han convocado. Sígueme.', '', 25549),
(122429, 'esES', 'Parece que nadie ha usado esta fuente en mucho tiempo.', '', 25549),
(122421, 'esES', 'Héroes de la Alianza, os escribo en el ocaso de Azeroth. Los ejércitos ardientes de la Legión han regresado del infierno.', '', 25549),
(122420, 'esES', 'Impresionante, tu arma y tu experiencia demuestran que incluso los Valarjar pueden aprender de las razas más jóvenes. Hay nuevos enemigos y nuevas formas de combate que no había visto en mi larga vida. Me has dado mucho en lo que pensar, gracias.', '', 25549),
(122419, 'esES', '¡Hacedlos retroceder! ¡No podemos perder la ciudad!', '', 25549),
(122418, 'esES', '¡Nos pillaron desprevenidos! ¡Hay que acabar con estos demonios de una vez por todas!', '', 25549),
(122417, 'esES', 'Si no detenemos a Xavius, la Pesadilla consumirá todo Azeroth.', '', 25549),
(122416, 'esES', 'Más vale tarde que nunca, ¿no, chaval? ¡Los que aún respiren, que sigan luchando! ¿Estáis pre...?', '', 25549),
(122415, 'esES', '¡No te quedes de brazos cruzados! ¡Estos demonios no se van a morir solos!', '', 25549),
(122414, 'esES', '¡$GSeñor:Señora; de la Guerra!', '', 25549),
(122413, 'esES', '|TInterface\\Icons\\spell_fire_ragnaros_molteninferno.blp:20|t¡El $n |cFFFF0000|Hspell:202663|h[Detona]|h|r al morir!', '', 25549),
(122412, 'esES', '¡Largo!', '¡Largo!', 25549),
(122411, 'esES', '', '¡Mezcla ya ese mojo, tenemoh que ir a la Cohta Abrupta!', 25549),
(122410, 'esES', '¡Despiértame de esta pesadilla!', '¡Despiértame de esta pesadilla!', 25549),
(122409, 'esES', 'Este lugar... Es mucho peor de lo que podría haber imaginado.', '', 25549),
(122408, 'esES', '|TInterface\\Icons\\sha_spell_shadow_shadesofdarkness_nightmare:20|t¡%s comienza a lanzar |cFFFF0000|Hspell:214876|h[Bestias de la Pesadilla]|h|r!', '', 25549),
(122407, 'esES', '', 'Lunargenta está contigo. Permítenos bendecir tu arma con poder Sagrado.', 25549),
(122406, 'esES', 'Una hoja demoníaca puede encontrar el más mínimo fallo en tu armadura. Repárala si no quieres que tu cabeza acabe en una pica.', '', 25549),
(122405, 'esES', '<Inserta 20 p. |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t de maná antiguo en la matriz de defensa.>', '<Inserta 20 p. |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t de maná antiguo en la matriz de defensa.>', 25549),
(122404, 'esES', '<Parece que la matriz de defensa no tiene energía.>', '', 25549),
(122403, 'esES', 'Tengo que regresar a la superficie.', 'Tengo que regresar a la superficie.', 25549),
(122402, 'esES', 'Sí tienes dudas sobre qué camino tomar, puedo devolverte a la superficie. ¿Quieres?', '', 25549),
(122401, 'esES', '', '¡Mis facultades no tienen rival!$b$bAunque he oído que tengo competencia. Que hay alguien fuera de la ciudad practicando la herrería.$b$bMe gustan los desafíos. ¡Adelante! ¡Ja, ja, ja!', 25549),
(122400, 'esES', '', 'Oh.$b$bA tu armadura le vendrían bien unos arreglos.', 25549),
(122399, 'esES', 'Te doy la bienvenida. ¿Qué puedo hacer por ti?', '', 25549),
(122398, 'esES', '', '¡Siéntate y relájate!', 25549),
(122397, 'esES', '', 'Nos hemos quedado sin vino, pero tenemos mucha comida, bebida y varias zonas de descanso.', 25549),
(122396, 'esES', '', '¡Hola, encanto!$b$b¿En qué puedo ayudarte?', 25549),
(122395, 'esES', '', 'El cristal está cargado. Úsalo como quieras.', 25549),
(122394, 'esES', '<Podretripa se vuelve hacia ti y eructa estentóreamente.>$b$bPodretripa... Podre... ¡tripa!', '', 25549),
(122393, 'esES', '', '¡Conjuradores, empezad a canalizar!', 25549),
(122392, 'esES', '¡Es $gel Guardián:la Guardiana; de G''Hanir! Contamos contigo, $n.', '¡Es $gel Guardián:la Guardiana; de G''Hanir! Contamos contigo, $n.', 25549),
(122391, 'esES', '¡Es $n! ¡$gEl héroe:La heroína; que purgó la corrupción de G''Hanir!', '¡Es $n! ¡$gEl héroe:La heroína; que purgó la corrupción de G''Hanir!', 25549),
(122390, 'esES', 'Me alegro de ver a G''Hanir en buenas manos.', 'Me alegro de ver a G''Hanir en buenas manos.', 25549),
(122389, 'esES', '¡Aquí está $gel Guardián:la Guardiana; de G''Hanir! ¡Que Elune te bendiga, $n!', '¡Aquí está $gel Guardián:la Guardiana; de G''Hanir! ¡Que Elune te bendiga, $n!', 25549),
(122388, 'esES', '¡Me alegro de que el Círculo Cenarion cuente con alguien como tú, $gportador:portadora; de los Colmillos!', '¡Me alegro de que el Círculo Cenarion cuente con alguien como tú, $gportador:portadora; de los Colmillos!', 25549),
(122387, 'esES', 'Dalaran se ha reubicado para defender los Reinos del Este. Se encuentra en el Paso de la Muerte, sobrevolando Karazhan. Te esperaré allí.', '', 25549),
(122386, 'esES', '$n, reconozco esas dagas. Son los Colmillos de Crinceniza, ¿verdad? Debes de haber impresionado a los Cinéreos para que te los hayan dejado.', '$n, reconozco esas dagas. Son los Colmillos de Crinceniza, ¿verdad? Debes de haber impresionado a los Cinéreos para que te los hayan dejado.', 25549),
(122385, 'esES', 'Soy reacio a interrumpir un trabajo tan importante, pero me vendría bien tu ayuda para un asunto... diplomático. Creo que voy a enfadar a una vieja amistad.', '', 25549),
(122384, 'esES', 'Saludos. Me han hablado de tus acciones para repeler la invasión de la Legión.', '', 25549),
(122383, 'esES', '¡Los Colmillos de Crinceniza! ¡Pensé que los Cinéreos no los perderían de vista!', '¡Los Colmillos de Crinceniza! ¡Pensé que los Cinéreos no los perderían de vista!', 25549),
(122382, 'esES', 'Esas dagas tienen un aspecto extraño. ¿Son... dientes?', 'Esas dagas tienen un aspecto extraño. ¿Son... dientes?', 25549),
(122381, 'esES', '¡Los Colmillos de Crinceniza! ¡Así que los rumores del ataque al santuario de los Cinéreos eran ciertos!', '¡Los Colmillos de Crinceniza! ¡Así que los rumores del ataque al santuario de los Cinéreos eran ciertos!', 25549),
(122380, 'esES', '', 'Tethys organizará nuestro transporte en uno de sus barcos. Nos alejaremos de la tierra y luego nos llevará hasta la orilla al abrigo de la oscuridad y de la niebla.\n\nAvísame cuando quieras partir, $n.', 25549),
(122379, 'esES', '¡Saludos, archidruida $n, $gelegido:elegida; de Ursoc!', '¡Saludos, archidruida $n, $gelegido:elegida; de Ursoc!', 25549),
(122378, 'esES', '¡$gNuestro campeón:Nuestra campeona; lleva las Garras de Ursoc! ¡Los días de la Legión están contados!', '¡$gNuestro campeón:Nuestra campeona; lleva las Garras de Ursoc! ¡Los días de la Legión están contados!', 25549),
(122377, 'esES', 'Los rumores son ciertos. ¡$n lleva las Garras de Ursoc!', 'Los rumores son ciertos. ¡$n lleva las Garras de Ursoc!', 25549),
(122376, 'esES', 'Esas garras parecen extremadamente afiladas. ¡Me alegro de que estés de nuestro lado!', 'Esas garras parecen extremadamente afiladas. ¡Me alegro de que estés de nuestro lado!', 25549),
(122375, 'esES', 'Te doy la bienvenida, shan''do. Es un honor conocer a quien blande la guadaña.', 'Te doy la bienvenida, shan''do. Es un honor conocer a quien blande la guadaña.', 25549),
(122374, 'esES', '¡La Guadaña de Elune! El final debe de estar cerca si necesitamos su poder para salvarnos.', '¡La Guadaña de Elune! El final debe de estar cerca si necesitamos su poder para salvarnos.', 25549),
(122373, 'esES', '¿Eso que llevas es la Guadaña de Elune? ¿Es verdad que te convierte en una bestia?', '¿Eso que llevas es la Guadaña de Elune? ¿Es verdad que te convierte en una bestia?', 25549),
(122372, 'esES', 'Cuidado con esa guadaña, shan''do. Me gustaría conservar el control de mi mente.', 'Cuidado con esa guadaña, shan''do. Me gustaría conservar el control de mi mente.', 25549),
(122371, 'esES', 'Elune-Ado... Espera, ¿eso que llevas es la Guadaña de Elune? ¡Increíble!', 'Elune-Ado... Espera, ¿eso que llevas es la Guadaña de Elune? ¡Increíble!', 25549),
(122370, 'esES', '', 'Se ha completado el ritual. ¡Contenlo, rápido!', 25549),
(122369, 'esES', '', '¡Sí, sí! ¡Funciona!', 25549),
(122368, 'esES', '', '¡Invocadores, comenzad el ritual!', 25549),
(122367, 'esES', '', 'Los crímenes de mi pasado son mi carga y no pretendo culpar a nadie de ellos, pero la Legión Ardiente corrompió a mi anterior orden y nos desvió de la rectitud.$b$b¡Les haré pagar semejante traición!', 25549),
(122366, 'esES', 'Esta acción cuesta 20 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná antiguo. ¿Quieres continuar?', 'Esta acción cuesta 20 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná antiguo. ¿Quieres continuar?', 25549),
(122365, 'esES', '<Alimenta al desdichado Nocheterna con 5 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná antiguo.>', '<Alimenta al desdichado Nocheterna con 5 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná antiguo.>', 25549),
(122364, 'esES', '¿Quieres fijar tu nuevo hogar en Shal''Aran?', '¿Quieres fijar tu nuevo hogar en Shal''Aran?', 25549),
(122363, 'esES', 'Quiero vincular mi piedra de hogar aquí.', 'Quiero vincular mi piedra de hogar aquí.', 25549),
(122362, 'esES', 'Me gustaría negociar.', 'Me gustaría negociar.', 25549),
(122361, 'esES', '', '¡Largo de aquí, alimaña!', 25549),
(122360, 'esES', '¡Zepelín suelto! ¡Cuidado todo el mundo!', '', 25549),
(122359, 'esES', '¡Apartaos! ¡Este zepelín va por libre!', '', 25549),
(122358, 'esES', '¡Cuidado! ¡No creo que pueda controlar esto!', '', 25549),
(122357, 'esES', '¡Quitaos de en medio! ¡Esto es muy peligroso!', '', 25549),
(122356, 'esES', '¡Apartaos! ¡A saber qué le pasa a este trasto!', '', 25549),
(122355, 'esES', '¿Qué buscas?', '', 25549),
(122354, 'esES', '', '¿Puedo ayudarte en algo?', 25549),
(122353, 'esES', 'Los Mano Destrozada recuperarán la antigua gloria de la Horda.', '', 25549),
(122352, 'esES', '¿Cómo puedes ayudarme, Sombra $n?', '', 25549),
(122351, 'esES', '', 'Estos elementales serán poderosos aliados en nuestra batalla contra la Legión Ardiente.', 25549),
(122350, 'esES', 'Saludos.', '', 25549),
(122349, 'esES', '¿Qué buscas?', '', 25549),
(122348, 'esES', '¿Qué puedo hacer por ti?', '', 25549),
(122347, 'esES', '', 'Espero que estos diablillos te sirvan bien.', 25549),
(122346, 'esES', '', 'Puedes apostar a que estos arqueros ponen la flecha donde ponen el ojo.', 25549),
(122345, 'esES', '¡Estos aspirantes Valarjar nos ayudarán a luchar contra la Legión Ardiente!', '', 25549),
(122344, 'esES', '¡Gusano despreciable!', '', 25549),
(122343, 'esES', '¡IN-FER-NO!', '', 25549),
(122342, 'esES', '¡Un gnomo insignificante! ¡Tu arrogancia será tu perdición!', '', 25549),
(122341, 'esES', '¡OS DESPELLEJARÉ!', '', 25549),
(122340, 'esES', 'Soy Jaraxxus, señor eredar de la Legión Ardiente.', '', 25549),
(122339, 'esES', '¡Gee! ¡Gee! ¿Te importaría recordarle al cajero Gee que sigo aquí, esperando pacientemente volver a mi estado natural? Muchas gracias.', '', 25549),
(122338, 'esES', '¡Ah, otro valioso cliente! ¡$GBienvenido, bienvenido:Bienvenida, bienvenida;!', '', 25549),
(122337, 'esES', '¡Todo está bien! Seguid con vuestros asuntos como de costumbre. ¡Lo tenemos todo bajo control!', '', 25549),
(122336, 'esES', 'Recuérdale a Gee que necesitaré pagos adicionales. Técnicamente sigo detrás del mostrador.', '', 25549),
(122335, 'esES', '¡Lo resolveremos en breve! Ten paciencia.', '', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(122334, 'esES', 'Esto es completamente normal. ¡No te preocupes!', '', 25549),
(122333, 'esES', '¡Sabemos cómo están las cosas y todo está bajo control!', '', 25549),
(122332, 'esES', '', '¿$GListo:Lista; para la revancha, $n? Cuando quieras y donde quieras.', 25549),
(122330, 'esES', 'Conseguiré ponerme a salvo. ¡No me capturarán otra vez!', 'Conseguiré ponerme a salvo. ¡No me capturarán otra vez!', 25549),
(122329, 'esES', 'Gr... Gracias. Empezaban a estar hambrientos...', 'Gr... Gracias. Empezaban a estar hambrientos...', 25549),
(122328, 'esES', 'Gracias por sacarme de ese terrible lugar.$b$bSe me dan muy bien las reparaciones. ¿Te haría falta mi ayuda con algo?', '', 25549),
(122327, 'esES', 'Tu tarjeta de sonido funciona perfectamente.', '', 25549),
(122326, 'esES', 'Pronóstico borroso, reúne 4289 cristales apexis y pregunta otra vez.', '', 25549),
(122325, 'esES', 'Poco probable... en esta realidad.', '', 25549),
(122324, 'esES', 'Deja que consulte con mis fuentes... Sí.', '', 25549),
(122323, 'esES', 'Deja que consulte con mis fuentes... No.', '', 25549),
(122322, 'esES', 'Es probable que sobrevivas. Muy probable.', '', 25549),
(122321, 'esES', 'Respuesta... borrosa... ¿Prueba otra vez?', '', 25549),
(122320, 'esES', 'La derrota está asegurada.', '', 25549),
(122319, 'esES', 'No hay duda del pronóstico: ¡muerte segura!', '', 25549),
(122318, 'esES', 'Nooooo... Ah, pues de hecho sí.', '', 25549),
(122317, 'esES', '', 'Resurjo, renovada, como escudo del hombre, mano de la devoción y espada de la reprensión.', 25549),
(122316, 'esES', 'He fallado a mi reino y a mi gente... No fallaré a nuestro mundo también.', '', 25549),
(122315, 'esES', 'Vuelve en un par de días, por favor. Nos interesa mucho hacer negocios contigo...', '', 25549),
(122314, 'esES', 'Nuestro personal está trabajando sin descanso para asegurar que tus pertenencias están a salvo. No hay nada que temer.', '', 25549),
(122313, 'esES', 'No hay motivos para preocuparse. No son más que los efectos secundarios de trasladar una ciudad mágica enorme.', '', 25549),
(122312, 'esES', 'Sí, sí, ya sabemos lo que parece. Todas tus valiosas pertenencias seguirán aquí cuando todo vuelva a la normalidad. Tienes mi palabra.', '', 25549),
(122311, 'esES', '¡Amigos! ¡Amigos! Por favor... Aunque parezca raro, está todo bajo control. Hemos contratado guardias adicionales para que no desaparezca nada.', '', 25549),
(122310, 'esES', '¡Atrás todo el mundo! Esto no es más que otro efecto secundario de la traslación de la ciudad. Todo volverá a la normalidad muy pronto.', '', 25549),
(122309, 'esES', 'Veamos qué tienes.', 'Veamos qué tienes.', 25549),
(122308, 'esES', 'Saludos, $n. Tengo algunas cosas que podrían serte útiles.', '', 25549),
(122307, 'esES', '', 'El oro da un toque incluso a los lugares oscuros como este.', 25549),
(122306, 'esES', '¿Qué tienes a la venta?', '¿Qué tienes a la venta?', 25549),
(122305, 'esES', '¿Qué tienes a la venta?', '¿Qué tienes a la venta?', 25549),
(122304, 'esES', '', 'Tu llama arde deslumbrante hoy, $n.', 25549),
(122303, 'esES', '¡No me *hip* interrumpas! Necesitamos el poder de la Fuente de la Noche...', '¡No me *hip* interrumpas! Necesitamos el poder de la Fuente de la Noche...', 25549),
(122302, 'esES', 'Hagas lo que hagas, no te comas la fruta de los cuencos.$b$bSon solo porquerías. Si quieres probar las delicias de Suramar, te ilustraré con sabores de verdad.', '', 25549),
(122301, 'esES', 'Veamos qué tienes.', 'Veamos qué tienes.', 25549),
(122300, 'esES', '', '¡Hola, $n! ¿En qué puedo ayudarte hoy?', 25549),
(122299, 'esES', 'Veamos qué tienes.', 'Veamos qué tienes.', 25549),
(122298, 'esES', '', '¡Hola, $n! ¿En qué puedo ayudarte hoy?', 25549),
(122297, 'esES', '', '¡No te dejaremos pasar, lady Keletress!', 25549),
(122296, 'esES', 'Veamos qué tienes.', 'Veamos qué tienes.', 25549),
(122295, 'esES', '$GBienvenido:Bienvenida;, $n. Tengo algunas cosas que podrían serte útiles.', '', 25549),
(122294, 'esES', '¡Victoria!', '', 25549),
(122293, 'esES', 'Que los elementos te sean favorables.', '', 25549),
(122292, 'esES', '', '$GBienvenido:Bienvenida;, $n. Que los celestiales velen por ti.', 25549),
(122291, 'esES', 'Veamos qué tienes.', 'Veamos qué tienes.', 25549),
(122290, 'esES', 'Mmm... ¿Hoy no hay ovejas especiales? ¡Vaya tela! Habrá que probar mañana, ¿no?', '', 25549),
(122289, 'esES', '', 'Normalmente, entrenar a los escuderos lleva su tiempo, pero me he dado prisa esta vez por ser tú.', 25549),
(122288, 'esES', '', '¿Cómo pudieron creer las mentiras del heraldo? Recuerda mis palabras: hay magia negra de por medio.\n\nPor favor, si puedes hacer algo para detener esto, hazlo ya. Se han perdido demasiadas vidas inocentes...', 25549),
(122287, 'esES', 'Si Toryl dice que has venido a ayudarnos, puedes descansar junto al fuego. ¡Prueba nuestra carne y nuestro hidromiel!', '', 25549),
(122286, 'esES', '¡Pues vaya! Cómo han cambiado las cosas.', '', 25549),
(122285, 'esES', 'En mi época estos árboles eran más verdes.', '', 25549),
(122283, 'esES', 'Veamos qué tienes.', 'Veamos qué tienes.', 25549),
(122282, 'esES', 'Tengo unos cuantos objetos que podrían serte útiles, $n.', '', 25549),
(122281, 'esES', 'Perdona el engaño, señor de la batalla. ¡Jamás interferiría en las pruebas, ni siquiera por mi adalid!', '', 25549),
(122280, 'esES', 'Estos necrófagos se someterán a tu voluntad.', '', 25549),
(122279, 'esES', 'Reclutar a un eco de un celestial', 'Reclutar a un eco de un celestial', 25549),
(122278, 'esES', '¡Hola!', '¡Hola!', 25549),
(122277, 'esES', 'Veamos qué tienes.', 'Veamos qué tienes.', 25549),
(122276, 'esES', '¿En qué puedo ayudarte, $n?', '', 25549),
(122275, 'esES', 'Que la gloria de Odyn te acompañe, Valarjar.', '', 25549),
(122274, 'esES', 'Reclutar a un anciano de la guerra', 'Reclutar a un anciano de la guerra', 25549),
(122273, 'esES', '<frufrú de hojas>', '<frufrú de hojas>', 25549),
(122272, 'esES', '¡Por aquí, $gamigo:amiga; $c! Este ofrece cosas brillantes. ¡Echa un ojo!', '', 25549),
(122271, 'esES', 'Comienza el ritual', 'Comienza el ritual', 25549),
(122270, 'esES', 'La vermis de escarcha quiere que la liberen.', '', 25549),
(122269, 'esES', 'He oído hablar de tus hazañas. Veamos si es cierto todo lo que cuentan.', '', 25549),
(122268, 'esES', 'Vaya, ¡pero si es el adalid de Odyn!', '', 25549),
(122266, 'esES', 'Te debo mi vida dos veces ya... No tengo mucho que ofrecer, pero puedes echar un vistazo a mis suministros y coger lo que quieras.', '', 25549),
(122265, 'esES', 'Si te gustan tus zapatos, quizás deberías dar un paso atrás.', '', 25549),
(122264, 'esES', 'Veamos qué tienes.', 'Veamos qué tienes.', 25549),
(122263, 'esES', '', 'Te doy la bienvenida a La Rama Retorcida, $n.', 25549),
(122262, 'esES', '¡Mira este desastre! ¡Todo desordenado! Libros en el suelo, herramientas por todas partes... ¡Ojalá nos avisaran con más antelación de los traslados de la ciudad!$b$bY mira a Dorian ahí. El pobre todavía se está recuperando.', '', 25549),
(122261, 'esES', '', 'Lo siento, $n, pero nos han pedido que no aceptemos alumnos durante un tiempo. Cuando lleguemos a nuestro destino final, todo volverá a la normalidad.', 25549),
(122260, 'esES', 'Haz un pedido de armamento de campeón', 'Haz un pedido de armamento de campeón', 25549),
(122259, 'esES', 'Tráeme a tus muertos y les encontraré alguna utilidad.', '', 25549),
(122258, 'esES', '¡Los Marchitos! Nos persiguen. ¡Por favor, ayúdame!', '', 25549),
(122257, 'esES', 'Espera... ¿Oyes eso?', '', 25549),
(122256, 'esES', 'Veamos qué tienes.', 'Veamos qué tienes.', 25549),
(122255, 'esES', 'Gr... Gracias... No... No sé cómo continuar... He perdido tanto...', '', 25549),
(122254, 'esES', '¿Qué necesitas, $gpequeño:pequeña; $n?', '', 25549),
(122253, 'esES', '<Alimenta a Llorian con 25 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná antiguo.>', '<Alimenta a Llorian con 25 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná antiguo.>', 25549),
(122252, 'esES', 'Haz un pedido de armamento de campeón', 'Haz un pedido de armamento de campeón', 25549),
(122251, 'esES', '', 'Que la Luz te bendiga.', 25549),
(122250, 'esES', 'La han matado... Esos Marchitos han matado a mi Luniel. No... No me queda nada.', '', 25549),
(122249, 'esES', 'Escucharé lo que este cazador de demonios tenga que decir.', '', 25549),
(122248, 'esES', '¡Tengo que terminar estas muestras, $n! ¡El último lote era tan inestable que casi nos mata al trasladarnos!$b$bEso último no se lo menciones a nadie.', '', 25549),
(122247, 'esES', 'Comienza el ritual', 'Comienza el ritual', 25549),
(122246, 'esES', '', '¿Es la hora?', 25549),
(122244, 'esES', 'Empezar a cargar el Martillo', 'Empezar a cargar el Martillo', 25549),
(122243, 'esES', '', '¿Sí?', 25549),
(122241, 'esES', 'Haz un pedido de armamento de campeón.', 'Haz un pedido de armamento de campeón.', 25549),
(122240, 'esES', '¿En qué puedo servir?', '¿En qué puedo servir?', 25549),
(122239, 'esES', 'Comenzar la llamada', 'Comenzar la llamada', 25549),
(122238, 'esES', '', '¿Qué necesitas?', 25549),
(122237, 'esES', 'Luniel... Dulce Luniel... ¿Cómo he podido permitir esto?', '', 25549),
(122236, 'esES', 'Haz un pedido de armamento de campeón.', 'Haz un pedido de armamento de campeón.', 25549),
(122235, 'esES', '¿Qué?', '', 25549),
(122232, 'esES', 'Dar el aviso a la vanguardia', 'Dar el aviso a la vanguardia', 25549),
(122231, 'esES', '¿Qué ordenas?', '', 25549),
(122230, 'esES', '|TInterface\\Icons\\spell_deathknight_necroticplague.blp:20|t ¡Te afecta una |cFFF00000|Hspell:206480|h[Peste carroñera]|h|r!', '', 25549),
(122229, 'esES', 'Por favor... mata a todos estos monstruos.', 'Por favor... mata a todos estos monstruos.', 25549),
(122228, 'esES', 'Libre... Libre por fin. ¿Cómo salgo de aquí?', 'Libre... Libre por fin. ¿Cómo salgo de aquí?', 25549),
(122227, 'esES', 'Creo... que lo conseguiré. Gracias.', 'Creo... que lo conseguiré. Gracias.', 25549),
(122226, 'esES', 'El horror... El horror.', 'El horror... El horror.', 25549),
(122225, 'esES', 'No puedo más...', 'No puedo más...', 25549),
(122224, 'esES', 'Estoy... tan débil...', 'Estoy... tan débil...', 25549),
(122223, 'esES', 'Si aún no has aprendido a volar aquí en Pandaria, puedes tomar prestado a Graddoc para volar al Valle.', '', 25549),
(122222, 'esES', 'La caja vuelve a brillar. ¡Una secuencia más y estará activada del todo!', 'La caja vuelve a brillar. ¡Una secuencia más y estará activada del todo!', 25549),
(122221, 'esES', 'La melodía de campanas aumenta su volumen.', 'La melodía de campanas aumenta su volumen.', 25549),
(122220, 'esES', 'La caja comienza a emitir unos sonidos de campanas muy agradables.', 'La caja comienza a emitir unos sonidos de campanas muy agradables.', 25549),
(122219, 'esES', 'La caja brilla intensamente.', 'La caja brilla intensamente.', 25549),
(122218, 'esES', 'La próxima vez que te digan que van a trasladar una ciudad usando magia, ya puedes prepararte para cualquier cosa. ¡LITERALMENTE!', '', 25549),
(122217, 'esES', 'Necesito que pulses el botón rojo enorme que dice: "NO PULSAR ESTE BOTÓN".', '', 25549),
(122216, 'esES', 'Pero también es posible que tengamos un pequeño caso de fallo total del sistema.', '', 25549),
(122215, 'esES', 'Si necesitas a Dorothy, está dentro, pero, si estás buscando suministros, de momento no podemos recibir pedidos. Lo siento.', '', 25549),
(122214, 'esES', '', 'Muchas personas vienen en busca de ayuda para los efectos secundarios.$b$bSi lograra encontrar esas viejas recetas... Sé que están por aquí.', 25549),
(122213, 'esES', '', 'Ah, no te preocupes por él. Es muy olvidadizo. Toda la mercancía antigua se almacenó antes de nuestro viaje.$b$bVuelve a visitarnos cuando la tienda esté abierta de nuevo. ¡Seguro que llegaremos a nuestro destino final muy pronto!', 25549),
(122212, 'esES', '¡Solo han llegado la mitad de mis quesos! ¡La mitad!$b$b¿Cómo voy a regentar una tienda de quesos y vino con un montón de vino y unos taquitos de queso? ¡Esto es un escándalo! ¡Es absurdo! Y...$b$b¡Uf, vaya! Ahora me siento débil. ¿Hasta dónde vamos a llegar?', '', 25549),
(122211, 'esES', '', '¡Estamos casi todos! ¿Quién habría pensado que trasladar Dalaran provocaría tantos problemas? Un redil más y los pájaros y todo volverán a la normalidad.$b$b<Mira alrededor de la sala>.$b$bExcepto por ese pobre que está en la pecera. Espero que lo resuelvan pronto.', 25549),
(122210, 'esES', '', '¡Este lugar es un caos!', 25549),
(122209, 'esES', '', 'Protegeré a los débiles, defenderé la justicia y seguiré el camino de la virtud.', 25549),
(122208, 'esES', '', 'Escudo del hombre, mano de la devoción y espada de la reprensión.', 25549),
(122207, 'esES', '', 'Soy una guerrera de la Luz.', 25549),
(122206, 'esES', '', 'Con este voto, renazco.', 25549),
(122205, 'esES', '', 'Y me uno a mis hermanos y hermanas en humilde servicio.', 25549),
(122204, 'esES', '', 'Entrego mi vida a la Orden de la Mano de Plata.', 25549),
(122202, 'esES', '', 'Aquí, en presencia de los campeones eternos, hago este sagrado juramento:', 25549),
(122201, 'esES', '<Alimenta al sable de maná con 10 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná antiguo.>', '<Alimenta al sable de maná con 10 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná antiguo.>', 25549),
(122200, 'esES', '<El sable de maná te mira como si llevaras algo de comer.>', '', 25549),
(122198, 'esES', 'Menos mal que la pecera se vació antes de irnos. ¡Imagínate lo que podría haber pasado!', '', 25549),
(122197, 'esES', 'No puedo hacer nada con la situación actual. ¡Agárrate fuerte! Ya pensaremos en algo.', '', 25549),
(122196, 'esES', 'Necesito más tiempo para pensar. Estas circunstancias son únicas. No es el tipo de trabajo que se pueda hacer... a medias.', '', 25549),
(122195, 'esES', 'No te preocupes, te sacaremos de aquí en nada... ¿Por qué sigo hablándole a esta cosa?', '', 25549),
(122194, 'esES', 'Si giramos un poco en la dirección de las agujas del reloj, quizás... No. A lo mejor era en la dirección contraria...', '', 25549),
(122193, 'esES', 'Pronuncia los votos en el altar cuando tengas todo listo.', 'Pronuncia los votos en el altar cuando estés lista.', 25549),
(122192, 'esES', 'Bueno, podemos esperar a que nos traslademos de nuevo. ¿Quién sabe? ¡Quizás el problema se arregle solo!', '', 25549),
(122191, 'esES', '', 'Vanthir pensó que aquí estaríamos a salvo. Después de lo que le pasó a mi querida Korine, tengo que darle la razón.\n\nLa vida que llevan los Caídos de la Noche es muy dura, pero aguantaremos.\n\nGracias otra vez por salvar a mi hija.', 25549),
(122190, 'esES', 'Potenciar el cristal de enfoque', 'Potenciar el cristal de enfoque', 25549),
(122189, 'esES', '', 'Ya podemos comenzar.', 25549),
(122188, 'esES', '¿Qué ha sido eso? ¡Para! ¡Alguien me está incordiando desde el otro lado!', '', 25549),
(122187, 'esES', '¿A qué te refieres con "hay que esperar a que volvamos a trasladarnos"? ¡No puedo quedarme aquí! ¡Tengo cosas que hacer!', '', 25549),
(122186, 'esES', 'No me había dado cuenta antes, pero las piedras del suelo están muy bien cuidadas.', '', 25549),
(122185, 'esES', '¡Sí, pero asegúrate de defenderme si aparecen los demonios! No puedo defenderme por mí mismo, ya sabes.', '', 25549),
(122184, 'esES', 'Ah, mira. Otro espectador. Claaaaro... Disfruta del espectáculo. Todo el mundo viene a ver al pobre gnomo. Cuando baje de aquí...', '', 25549),
(122183, 'esES', '¡Oye! ¡Más despacio! Me gustaría conservar intactas las piernas si es posible... ¡Un momento! Si estoy aquí... ¡¿dónde está el resto?!', '', 25549),
(122182, 'esES', 'Especialista, ¿eh? ¡Llevo horas atrapado!', '', 25549),
(122181, 'esES', 'El sable de maná ronronea suavemente para que te acerques.', '', 25549),
(122180, 'esES', '', 'Me hice sacerdotisa para ayudar a la gente, pero últimamente me ha dado por preguntarme si podría hacer más.', 25549),
(122179, 'esES', 'Reclutar ascendientes', 'Reclutar ascendientes', 25549),
(122178, 'esES', 'A los Ascendidos no se les puede dar órdenes, solo se puede liberarlos.', 'A los Ascendidos no se les puede dar órdenes, solo se puede liberarlos.', 25549),
(122177, 'esES', '<Alimenta al tejedor de fuego Ovin con 25 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná antiguo.>', '<Alimenta al tejedor de fuego Ovin con 25 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná antiguo.>', 25549),
(122176, 'esES', 'Mi llama... se debilita. No voy a durar mucho...', '', 25549),
(122175, 'esES', 'Haz un pedido de sello de destino alterado.', 'Haz un pedido de sello de destino alterado.', 25549),
(122174, 'esES', '¡Ponte las gafas de espionaje elegantes para localizar el reguero de sangre!', '¡Ponte las gafas de espionaje elegantes para localizar el reguero de sangre!', 25549),
(122173, 'esES', 'Los Descoronados debemos intentar debilitar a la Legión Ardiente como mejor sabemos: artificios, argucias, engaños y, por supuesto, política.\n\nHasta que derrotemos a la Legión, nuestra cooperación es mi principal prioridad, $n. Supongo que la tuya también.', '', 25549),
(122172, 'esES', '<Alimenta a la tempomante Virinya con 25 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná antiguo.>', '<Alimenta a la tempomante Virinya con 25 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná antiguo.>', 25549),
(122171, 'esES', '', 'Ayuda... por favor. Mis pensamientos... se ralentizan.', 25549),
(122170, 'esES', 'Aceptaremos tu ayuda gustosos, Delas. La Luz se fortalece en la unión.', '', 25549),
(122169, 'esES', '¡He encontrado uno! Asegurad esta zona de inmediato.', '', 25549),
(122168, 'esES', '¡La Legión temblará ante mí! ¡Todos temblarán ante mí!', '', 25549),
(122167, 'esES', '¡Vuestra energía vital amplifica la mía! ¡Soy imparable!', '', 25549),
(122166, 'esES', '¡Seré el instrumento de la venganza de Azeroth!', '', 25549),
(122165, 'esES', '¡Debéis morir para que yo pueda vivir! ¡Tengo un destino que cumplir! ¡Un mundo que salvar!', '', 25549),
(122164, 'esES', 'Gracias por este sacrificio. Vuestra muerte no será en vano.', '', 25549),
(122163, 'esES', 'Ojalá hubiera otra forma, pero debo obtener poder para que sobrevivamos.', '', 25549),
(122162, 'esES', 'Tu energía vital le dará una oportunidad a nuestro mundo.', '', 25549),
(122161, 'esES', 'Yo no pedí esta carga, pero el destino me la ha impuesto...', '', 25549),
(122160, 'esES', 'Has tomado una senda oscura, Illidan. Ya no hay vuelta atrás...', 'Has tomado una senda oscura, Illidan. Ya no hay vuelta atrás...', 25549),
(122159, 'esES', '¡Madre Luna, llévame!', '¡Madre Luna, llévame!', 25549),
(122158, 'esES', 'Illidan... ¿Por qué?', 'Illidan... ¿Por qué?', 25549),
(122157, 'esES', '¡¿No veis los sacrificios que debo hacer para garantizar nuestra supervivencia?!', '', 25549),
(122156, 'esES', 'Me aseguraré de que tu familia esté bien protegida, camarada.', '', 25549),
(122155, 'esES', 'La amenaza de la Legión cuesta vidas. ¡Vuestras vidas!', '', 25549),
(122154, 'esES', '¡No podéis juzgarme! ¡Lo que hago, lo hago por Azeroth!', '', 25549),
(122153, 'esES', '¡Algunos de vosotros tendréis que morir para que este mundo sobreviva!', '', 25549),
(122152, 'esES', '¡Tienes suerte de haber tenido esta oportunidad de prestar servicio!', '', 25549),
(122151, 'esES', '¡Mira a tu alrededor! ¡Es la única manera!', '', 25549),
(122150, 'esES', '¡Ahora secundas un propósito más alto, fiel sirviente!', '', 25549),
(122149, 'esES', '¡Hago lo que es necesario!', '', 25549),
(122148, 'esES', '¿Quieres magia? ¡Prueba esto!', '¿Quieres magia? ¡Prueba esto!', 25549),
(122147, 'esES', '¡Arderás por esto, Illidan!', '¡Arderás por esto, Illidan!', 25549),
(122146, 'esES', '¡TRAIDOR!', '¡TRAIDOR!', 25549),
(122145, 'esES', '¡No eres mejor que los demonios que nos atacan!', '¡No eres mejor que los demonios que nos atacan!', 25549),
(122144, 'esES', '¿Quieres mi maná? ¡Ven a por él si te atreves!', '¿Quieres mi maná? ¡Ven a por él si te atreves!', 25549),
(122143, 'esES', '¡Nos has traicionado a todos!', '¡Nos has traicionado a todos!', 25549),
(122142, 'esES', '¡Ya no eres mi capitán, Illidan! ¡MUERE!', '¡Ya no eres mi capitán, Illidan! ¡MUERE!', 25549),
(122141, 'esES', '¡Guardia del Torreón, mandad a esos diablos con sus oscuros maestros! ¡Por Azshara! ¡Por Kalimdor!', '', 25549),
(122140, 'esES', '¡No caeré sin luchar!', '¡No caeré sin luchar!', 25549),
(122139, 'esES', '¡Eres un monstruo, Illidan!', '¡Eres un monstruo, Illidan!', 25549),
(122138, 'esES', 'Mis cadenas te atarán.', '', 25549),
(122137, 'esES', 'Haz un pedido de armamento de campeón.', 'Haz un pedido de armamento de campeón.', 25549),
(122136, 'esES', 'Puedo ayudarte a conseguir algunos objetos de valor.', 'Puedo ayudarte a conseguir algunos objetos de valor.', 25549),
(122135, 'esES', '¡Para! ¡Nos estás matando!', '¡Para! ¡Nos estás matando!', 25549),
(122134, 'esES', 'No puedes hacer esto, Illidan.', 'No puedes hacer esto, Illidan.', 25549),
(122133, 'esES', 'No puedo moverme... mi poder...', 'No puedo moverme... mi poder...', 25549),
(122132, 'esES', 'Mi poder mengua...', 'Mi poder mengua...', 25549),
(122131, 'esES', 'M... Maestro... Muero...', 'M... Maestro... Muero...', 25549),
(122130, 'esES', '¿Tiburones de alcantarilla? Criaturas asquerosas, solo las había visto una vez antes.', '', 25549),
(122129, 'esES', '¡Pide una cerveza caliente y salchichas frías! ¡Pregunta por Palomino y dile que vienes de parte de Joe!', '', 25549),
(122128, 'esES', '¿Alguien ha visto a mi hermano Daryl?', '', 25549),
(122127, 'esES', '¿Qué es ese olor?', '', 25549),
(122126, 'esES', 'Las cosas no pueden ir peor. ¿Verdad?', '', 25549),
(122125, 'esES', '¡Ahora a la derecha! ¡Ahora a la izquierda!', '', 25549),
(122123, 'esES', '¿Alguien ha visto a Apestoso? Me estoy empezando a preocupar.', '', 25549),
(122122, 'esES', '¡Este chaleco no es gratis!', '', 25549),
(122120, 'esES', 'Mi mujer me ha dejado por una solla.', '', 25549),
(122119, 'esES', 'El camino es largo, $gamigo:amiga;.\n\n¿Te echo una mano?', '', 25549),
(122118, 'esES', '', 'Ah, hola, bomboncito. Si necesitas algo, o quieres que alguien te traiga algo...\n\nO, ya sabes, si quieres hablar, aquí está Nikki.', 25549),
(122117, 'esES', '¿Sí? ¿Qué quieres?$b$bDisculpa que sea tan brusco, pero he pedido muchas veces que me avisen antes de decidir trasladar la ciudad. Ahora mira mi tienda... ¡Hay cosas por todas partes! ¡Ildine y Vanessa van a estar ocupadas durante meses!$b$bAhora, si me disculpas, debo terminar estos encantamientos antes de que nos traslademos de nuevo.', '', 25549),
(122116, 'esES', '¡Gracias!', '', 25549),
(122115, 'esES', '¡Revelaré al enemigo cuando tú me digas!', '', 25549),
(122114, 'esES', '', 'Sufre bien, $n. Estaremos listos cuando nos necesites.', 25549),
(122113, 'esES', '', 'Hasta el artesano más entregado necesita descansar de vez en cuando. Toma una manta de piel y reposa a salvo junto a mi chimenea.', 25549),
(122112, 'esES', 'Será mejor que vayas directamente al Fuerte Grommash, $n.', '', 25549),
(122111, 'esES', 'Esta acción cuesta 25 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná antiguo. ¿Quieres continuar?', 'Esta acción cuesta 25 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná antiguo. ¿Quieres continuar?', 25549),
(122110, 'esES', '<Alimenta al tejeley Ke''lorin con 25 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná antiguo.>', '<Alimenta al tejeley Ke''lorin con 25 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t p. de maná antiguo.>', 25549),
(122109, 'esES', 'Esto parece diferente. El aire parece normal, pero noto algo extraño.$b$bLa gente está haciendo cosas raras desde que llegamos. Y no me refiero a los mareos del viaje, más bien al ánimo de la gente y los rumores que se oyen por ahí.', '', 25549),
(122108, 'esES', 'Mi mente... se marchita... Necesito... ayuda.', '', 25549),
(122107, 'esES', '[PH] ¡Y luego se reproduce una escena de vídeo final impresionante! [PH]', '[PH] ¡Y luego se reproduce una escena de vídeo final brutal! [PH]', 25549),
(122106, 'esES', 'Volveré cuando pueda pagar lo que me pides, Arluin.', 'Volveré cuando pueda pagar lo que me pides, Arluin.', 25549),
(122105, 'esES', 'Escribo hilos cuando siento cosas.', '', 25549),
(122104, 'esES', '', 'Los ataques drógbar han dejado a mi familia con poco que ofrecer, pero lo que tenemos es tuyo, $ghéroe:heroína;.', 25549),
(122103, 'esES', '', '$gBienvenido, forastero:Bienvenida, forastera;.$b$bLos tuyos no suelen prodigarse por estas alturas de la montaña, pero eres $gbienvenido:bienvenida; de todos modos.', 25549),
(122102, 'esES', '¿Quién será el próximo en probar mi acero?', '', 25549),
(122100, 'esES', '¿Qué? ¡Oh, ni siquiera sabía que estuvieses aquí! ¿Desde cuándo sois tan sigilosos los de tu clase?$b$bNecesitaría saber si nos vamos a ir pronto, para preparar mis cosas.', '', 25549),
(122099, 'esES', 'Ven, $gviajero:viajera;. Únete a nosotros.$b$bQue nuestro hogar sea el tuyo.$b$bQuédate aquí. Con nosotros.$b$bCon nosotros...', '', 25549),
(122098, 'esES', '¿$gUn cazadora:Una cazadora; de demonios? ¡Qué asco! Vuestras alas son ásperas y dan repelús.', '¿$gUn cazadora:Una cazadora; de demonios? ¡Puaj! Vuestras alas son ásperas y dan repelús.', 25549),
(122097, 'esES', '', 'No mentías, Elias. Los cazadores de demonios andan sueltos. Ten cuidado: con esos ojos, $n lo ve todo.', 25549),
(122096, 'esES', 'Me alegro de volver a verte, $n. Te encuentras bien, ¿verdad?\n\n<Mathias mira a su alrededor y continúa en voz baja.>\n\n¿Cómo va todo con los Descoronados? Como líder del IV:7, no puedo ayudarte públicamente.\n\nNo obstante, hasta que la guerra contra la Legión Ardiente toque a su fin, tendrás todo mi apoyo, aunque sea en secreto.\n\nHasta la vista.', '', 25549),
(122095, 'esES', 'Quiero reclutar doncellas escuderas.', 'Quiero reclutar doncellas escuderas.', 25549),
(122094, 'esES', 'Quiero reclutar Val''kyr.', 'Quiero reclutar Val''kyr.', 25549),
(122093, 'esES', 'Coge una piedra de reposo, brul. Navarrogg dice que puedes descansar aquí.', '', 25549),
(122092, 'esES', '', '¡$GUn cazador:Una cazadora; de demonios! Perfecto, eres justo lo que necesito.', 25549),
(122091, 'esES', '¿Eres $guno:una; de ellos, $n? ¿O de nosotros? Cuánta energía demoníaca...', '', 25549),
(122090, 'esES', '', 'Espero que conserves el control de tus... facultades... en este lugar sagrado, "$gcazador:cazadora; de demonios". Te vigilaremos.', 25549),
(122089, 'esES', '¿Qué te has hecho, $n? Tienes más de demonio que de $r.', '¿Qué te has hecho, $n? Tienes más de demonio que de $r.', 25549),
(122088, 'esES', '<murmullos>', '', 25549),
(122087, 'esES', '', '¡Vaya, un campeón inventando excusas!', 25549),
(122086, 'esES', 'Soy tu campeón, Dama Oscura. Hacerte quedar bien es parte de mi trabajo.', '', 25549),
(122085, 'esES', 'Jace Tejeoscuro decía la verdad. ¡Llevas las Hojas de Guerra Aldrachi, $n! Contigo al frente de nuestra orden, los Illidari serán imparables.', 'Jace Tejeoscuro decía la verdad. ¡Llevas las Hojas de Guerra Aldrachi, $n! Contigo al frente de nuestra orden, los Illidari serán imparables.', 25549),
(122084, 'esES', '', 'Llevo muchas más muertes a mis espaldas que tú, Nathanos. ¡Te estás quedando atrás!', 25549),
(122083, 'esES', '¡$n! Veo que te has hecho con las hojas de Varedis Alma Vil. Esperemos que tú sepas controlar mejor a tu demonio interior.', '¡$n! Veo que te has hecho con las hojas de Varedis Alma Vil. Esperemos que tú sepas controlar mejor a tu demonio interior.', 25549),
(122082, 'esES', 'Usa la Guía con frecuencia, el poder de la Luz es infinito y generoso.', '', 25549),
(122081, 'esES', '$GBienvenido:Bienvenida; a bordo, $n.\n\nTenemos provisiones y estamos listos para zarpar cuando nos digas.', '', 25549),
(122080, 'esES', 'Tu bastón, como el cristal de Velen, es un regalo que otorgamos a los que intentamos salvar de la destrucción. Quedan pocos, así que no dejes que caiga en el Vacío.', '', 25549),
(122079, 'esES', 'De todos sus portadores, los que mejor han empuñado la Guía han sido los draenei. Esperemos que sobrevivan.', '', 25549),
(122078, 'esES', 'La Guía estuvo en silencio durante un tiempo. Me alegro de que la hayas recuperado.', '', 25549),
(122077, 'esES', 'Madre... Padre...', '', 25549),
(122076, 'esES', '', 'He escuchado muchas historias de estos dos héroes. No me cabe duda de que su mensaje es de máxima importancia.', 25549),
(122075, 'esES', 'Arator tiene razón. Turalyon y Alleria hicieron un gran esfuerzo por advertirnos. $GAlto Señor:Alta Señora;, recurrimos a ti. ¿Qué debemos hacer?', '', 25549),
(122074, 'esES', 'Si no lo llego a ver con mis propios ojos, no me lo creo.', '', 25549),
(122073, 'esES', '', 'Turalyon y Alleria... No puedo creer que estén vivos después de tantos años...', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(122072, 'esES', '', 'Por la Luz... ¿Qué significa eso?', 25549),
(122071, 'esES', '', '¡Revelaré la amenaza oculta cuando tú me digas!', 25549),
(122070, 'esES', '¿Por qué resbala tanto la manteca de cacao? ¡TRAEDME UNA TOALLA! ¡Quien la haya comprado está despedido!', '', 25549),
(122069, 'esES', '$GBienvenido:Bienvenida; a la tienda, $n. Lamento el desorden, estamos en proceso de limpieza.$b$b¡Esa última traslación lo puso todo patas arriba!', '', 25549),
(122068, 'esES', '', 'Discúlpame. De vez en cuando me dan mareos. Empezaron justo nada más llegar.', 25549),
(122067, 'esES', '', 'Qué de papeles. ¿Cómo los teníamos organizados? Están desperdigados por el suelo.$b$b¡Me llevará semanas volver a ordenarlos!', 25549),
(122066, 'esES', '', '¡Ah, no te había visto!$b$bHemos estado muy ocupados limpiando. Ven a vernos cuando estemos operativos de nuevo.', 25549),
(122065, 'esES', 'Disculpa el desorden. Hemos estado limpiando desde hace unos días.$b$b<Mira alrededor de su tienda>. Aunque no parece servir de nada. Parece como si hubiera entrado un vendaval. Y mi mercancía está dañada. ¿Quién la querrá ahora?$b$bLa próxima vez que decidamos mover la ciudad, lo ataré todo antes con correas.', '', 25549),
(122064, 'esES', 'Mmm... Nada, $n. Todos los pedidos se han paralizado hasta nueva orden.$b$bTodo esto está arruinado. Trasladar una ciudad... ¿A quién se le ocurrió? Tardaré semanas en recuperarme.', '', 25549),
(122063, 'esES', '', 'Dadas las circunstancias, sería inteligente por tu parte no convertir esta posada en tu hogar. Quizás no estemos en este mismo lugar la próxima vez que vuelvas.', 25549),
(122062, 'esES', '', '¡Aaah!', 25549),
(122061, 'esES', '¿Sabes lo que está pasando?', '¿Sabes lo que está pasando?', 25549),
(122060, 'esES', '', '¿Tú también lo notas? Tengo la piel de gallina...', 25549),
(122059, 'esES', '', 'Ufff... Esa espada... ¿Qué es lo que llevas? ¡Traes enfermedad y podredumbre, caballero de la Muerte!', 25549),
(122058, 'esES', '', 'Esa hoja demoníaca que llevas... rezuma corrupción, caballero de la Muerte. Haz lo que tengas que hacer y aleja esa hoja de este templo sagrado.', 25549),
(122057, 'esES', 'Un aura de enfermedad y pestilencia rodea la hoja que portas, caballero de la Muerte. Aléjate de Senegos.', '', 25549),
(122056, 'esES', '', 'Así que los rumores que corren por Entrañas son ciertos: ¡Agonía de Escarcha, reforjada! Ándate con ojo, $n. Esas hojas pueden tener vida propia.', 25549),
(122055, 'esES', '¿Qué blasfemia es esta, $n? ¿Cómo osas reforjar esa espada maldita, la que condenó a Lordaeron y su príncipe? Advertí a Arthas de que no tocara Agonía de Escarcha y ahora te advierto a ti: arroja esas cosas al mar antes de que nos condenen a todos.', '', 25549),
(122054, 'esES', '', '¿Eso es... la Fauce del Maldito? Así que volviendo una de las armas de la Legión en su contra, ¿eh? ¡Me gusta cómo piensas, $n!', 25549),
(122053, 'esES', '¡El que haya sido lo va a pagar! ¡Catetos! ¡Encontradlos! ¡ENCONTRADLOS!', '', 25549),
(122052, 'esES', 'Un momento... Una de mis llaves... ¡HAN ROBADO LA LLAVE DE MI CAJA FUERTE!', '', 25549),
(122051, 'esES', 'Uf... Empieza a hacer calor aquí. Creo que es la hora de la siesta.', '', 25549),
(122050, 'esES', '¡Muy bien! ¡Listo para aplastar cráneos!', '', 25549),
(122049, 'esES', '¡Catetos! ¡¿Dónde está mi manteca de cacao?! ¡¿Qué parte de MANTECA y CACAO no entendéis?!', '', 25549),
(122048, 'esES', 'Bueno, me voy a la sauna a relajarme... ¡Traedme un cóctel helado y manteca de cacao!', '', 25549),
(122047, 'esES', 'Esa hacha que llevas... es un arma de la Legión. ¿Seguro que puedes controlar su hambre?', '', 25549),
(122046, 'esES', 'Placeholder text.', '', 25549),
(122045, 'esES', '¡Escuchad, catetos! ¡El palacete está PROHIBIDO! ¡No quiero que NADIE ponga un pie en mi propiedad!', '', 25549),
(122044, 'esES', 'Sin texto', '', 25549),
(122043, 'esES', '¡Si te acercas a la sauna podrás hacerte con la llave!', '', 25549),
(122042, 'esES', '¡Hoy es tu día de suerte, $gamigo:amiga;! Precisamente ahora, Gallywix está disfrutando de su sauna personal.', '', 25549),
(122041, 'esES', 'Muerte a la Legión.', '', 25549),
(122040, 'esES', '', 'Esas hojas que llevas... están malditas. ¡Por favor, no traigas el frío de la muerte a este lugar sagrado!', 25549),
(122039, 'esES', '', 'Azeroth no debe caer.', 25549),
(122038, 'esES', '', 'Si se niega a hablar, recuérdale que me debe una por "lo que ya sabe" en "donde ya sabe"... ¿de acuerdo?', 25549),
(122037, 'esES', '', 'Habla con Izak, el camarero. Él debería saber cómo conseguir la llave de la caja fuerte.', 25549),
(122036, 'esES', '', 'Lord Illidan conoce el camino.', 25549),
(122035, 'esES', '', 'Cada vez que nos trasladamos, tengo que pasar días reorganizando mi colección. Ojalá hubiera un modo más fácil de recoger este desastre.', 25549),
(122034, 'esES', '¡Tendremos a tortolitos ciegos de amor dándonos su dinero en menos que nada!', '', 25549),
(122033, 'esES', '¡Este va a ser el robo del siglo!', '', 25549),
(122032, 'esES', '', 'Somos lo único que se interpone entre la Legión y el exterminio.', 25549),
(122031, 'esES', '', 'Por favor, caballero de la Muerte, no profanes este lugar sagrado con esa hacha perversa que llevas. Siento su hambre desde aquí.', 25549),
(122030, 'esES', '', 'No es tuyo... Ese cetro no es tuyo...', 25549),
(122029, 'esES', '', '¿Cómo osas reclamar para ti el cetro de nuestra querida reina...?', 25549),
(122028, 'esES', '¡Vas a pagar por fisgonear!', '', 25549),
(122027, 'esES', '', 'Ese cetro pertenece a nuestra reina...', 25549),
(122026, 'esES', '¡Tenemos un intruso!', '', 25549),
(122025, 'esES', '¡No deberías estar aquí!', '', 25549),
(122024, 'esES', '', 'Ese cetro no es tuyo, chamán. ¡Devuélvelo!', 25549),
(122023, 'esES', '¡Me pone furioso que te escabullas!', '', 25549),
(122022, 'esES', '¡Te voy a hacer papilla!', '', 25549),
(122021, 'esES', '¡Te pillé! ¡Vas a morir!', '', 25549),
(122020, 'esES', '¡Ahí estás! ¡Te voy a dar lo tuyo!', '', 25549),
(122019, 'esES', '¡Alguien se esconde por aquí!', '', 25549),
(122018, 'esES', '¡Sé que estás ahí! ¡Déjate ver!', '', 25549),
(122017, 'esES', '¡Asoma la cola, ratita!', '', 25549),
(122016, 'esES', '¡Hay alguien por aquí!', '', 25549),
(122015, 'esES', '¡Mi señor! Se acerca $gun forastero:una forastera; con un arma que lleva la marca de la propia reina Azshara.', '¡Mi señor! Se acerca $gun forastero:una forastera; con un arma que lleva la marca de la propia reina Azshara.', 25549),
(122014, 'esES', '¿Qué es ese ruido?', '', 25549),
(122013, 'esES', '¡Hay alguien husmeando!', '', 25549),
(122012, 'esES', '¡¿Quién anda por ahí?!', '', 25549),
(122011, 'esES', 'Cuídate.', '', 25549),
(122010, 'esES', 'Estoy $glisto:lista;.', 'Estoy $glisto:lista;.', 25549),
(122009, 'esES', 'Algo me huele a chamusquina aquí... Desde que llegamos, la gente se ha estado comportando de un modo extraño. Y el Consejo... se está reuniendo muy a menudo. Espero que todo vaya bien.', '', 25549),
(122008, 'esES', '', 'Hay demasiada calma desde el traslado. Igual es que la gente aún está tocada. ¡Cambiar de sitio toda Dalaran no es fácil!$b$bEspero que las cosas vuelvan a la normalidad pronto.', 25549),
(122007, 'esES', 'La locura me arrastra al más allá.', '', 25549),
(122006, 'esES', 'El abismo susurra tu nombre.', '', 25549),
(122005, 'esES', 'Se mueve, sin rostro y en el olvido... Inmortal.', '', 25549),
(122004, 'esES', 'Si no tienes esperanza, no puedes perderla.', '', 25549),
(122003, 'esES', '¡Mortal inútil! No puedes ganar...', '', 25549),
(122002, 'esES', '¡Mi maestro destrozará tu alma!', '', 25549),
(122001, 'esES', 'La oscuridad... me aguarda...', '', 25549),
(122000, 'esES', 'Mi vida... por mi maestro...', '', 25549),
(121999, 'esES', 'Si no puedo doblegar tu mente... ¡quebraré tus huesos!', '', 25549),
(121998, 'esES', 'Te mostraré lo que les ocurre a los héroes.', '', 25549),
(121997, 'esES', 'No me hagas reír... ¡Pide ayuda!', '', 25549),
(121996, 'esES', 'No podrás detener lo que se aviene... Ni en tus sueños.', '', 25549),
(121995, 'esES', '¡La Pesadilla te consumirá!', '', 25549),
(121994, 'esES', '¡Tu tormento no tendrá fin!', '', 25549),
(121993, 'esES', 'Te enviaré al sueño eterno.', '', 25549),
(121992, 'esES', '', 'Lo siento, $n. Con todo este jaleo no creo que vuelva a cortar el pelo en una temporada. La mayoría de mercaderes también han cerrado sus tiendas.$b$b<Mira alrededor, a los otros mercaderes.>$b$bSe rumorea que ha pasado algo y no solo por aquí. Las ciudades están llenas de... bueno, no sé, y no debería hablar más. No quiero ver a nadie más de los nervios por aquí. Ya tenemos suficiente.', 25549),
(121991, 'esES', '¡Sé presa de la oscuridad!', '', 25549),
(121990, 'esES', 'Me ha enviado Trixyni. Necesito la llave de la caja fuerte... Dice que "se lo debes".', 'Me ha enviado Trixyni. Necesito la llave de la caja fuerte... Dice que "se lo debes".', 25549),
(121989, 'esES', 'Idiota... Esta tierra ya está condenada...', '', 25549),
(121988, 'esES', 'Si buscas problemas, yo no quiero saber nada... ¿A quién pretendo engañar? ¡Cualquier cosa es mejor que esto!', '', 25549),
(121987, 'esES', '¡Esta es tu pesadilla!', '', 25549),
(121986, 'esES', 'La Pesadilla... me recibe...', '', 25549),
(121985, 'esES', '¿Morirías por esta patética tierra?', '', 25549),
(121984, 'esES', 'Lástima. Podrías unirte a nosotros...', '', 25549),
(121983, 'esES', '¿Buscas pelea? Permíteme...', '', 25549),
(121982, 'esES', '¿Llorarán por ti los elfos de la noche?', '', 25549),
(121981, 'esES', 'No nos detendrás. ¡Somos legión!', '', 25549),
(121980, 'esES', 'Yo te he avisado.', '', 25549),
(121979, 'esES', 'Algún día lo entenderás.', '', 25549),
(121978, 'esES', '¡Es inútil resistirse!', '', 25549),
(121977, 'esES', 'Me envía Tragonublo. Tengo que abrir la caja fuerte.', 'Me envía Tragonublo. Tengo que abrir la caja fuerte.', 25549),
(121976, 'esES', '¡Esta tierra está perdida!', '', 25549),
(121975, 'esES', '¡No puedes huir del Señor de la Pesadilla!', '', 25549),
(121974, 'esES', 'Maestro…', '', 25549),
(121973, 'esES', '', 'Sssh... ¡Baja la voz! ¡Si alguien nos ve hablando, estamos $gmuertos:muertas;!', 25549),
(121972, 'esES', 'Tu mundo está... condenado...', '', 25549),
(121971, 'esES', '¡Ríndete! Ya no queda esperanza...', '', 25549),
(121970, 'esES', 'La muerte... no nos detendrá...', '', 25549),
(121969, 'esES', 'Mis manos no son las únicas... manchadas de sangre...', '', 25549),
(121968, 'esES', 'Raaarrgh...', '', 25549),
(121967, 'esES', 'Solo te aguarda... el terror...', '', 25549),
(121966, 'esES', 'El maestro hará arder este mundo... ¡Y a ti con él!', '', 25549),
(121965, 'esES', '¡Pronto me suplicarás que te mate!', '', 25549),
(121964, 'esES', 'No puedes... huir... de tus sueños...', '', 25549),
(121963, 'esES', '¡Creo... que me lo he hecho encima! ¡No me mates, por favor!', '', 25549),
(121962, 'esES', 'Mientras estás por ahí, nos asentaremos más cerca del santuario. Que Elune te guíe.', '', 25549),
(121961, 'esES', '¡Fue el IV:7! ¡Nos ofrecieron los tesoros de Ventormenta a cambio de Amber Kearnen!', '', 25549),
(121960, 'esES', '¡Cielos, no! He oído hablar de ti... ¡No me mates!', '', 25549),
(121959, 'esES', 'Ahora que lo dices... Tu jeta me suena.', '', 25549),
(121958, 'esES', '¡No hablaré!', '', 25549),
(121957, 'esES', '¡Traedme su cabeza y La Hoja Roja tendrá libre acceso a la bahía de Ventormenta y un perdón real por sus crímenes pasados!', '', 25549),
(121956, 'esES', 'Yo, el maestro Mathias Shaw, autorizo por la presente a La Hoja Roja a dar caza a la fugitiva Amber Kearnen.', '', 25549),
(121955, 'esES', '¡Debes permanecer en la Cima del Templo!', '¡Debes permanecer en la Cima del Templo!', 25549),
(121954, 'esES', 'La Mano de Plata...', '', 25549),
(121953, 'esES', 'Veraguardia...', '', 25549),
(121952, 'esES', 'Todo dispuesto para comenzar la misión.', 'Todo dispuesto para comenzar la misión.', 25549),
(121951, 'esES', '¡Bien dicho!', '', 25549),
(121950, 'esES', 'Por supuesto.', '', 25549),
(121949, 'esES', '', 'Acepto tu juramento de lealtad, $n. ¡La Horda perdura!', 25549),
(121948, 'esES', 'Ojo avizor, $n... ¡Hay perros de agua salada a la vista!', '', 25549),
(121947, 'esES', 'Desde que la Legión ha perturbado nuestra red de transporte de largo alcance, viajar es... un desafío.', '', 25549),
(121946, 'esES', 'Necesito tu energía vital, fiel Guardia Lunar.', '', 25549),
(121945, 'esES', 'Necesito más poder para ganar esta batalla...', '', 25549),
(121944, 'esES', 'Perdonadme por esto.', '', 25549),
(121943, 'esES', 'Aún no es mi hora, pero sí la tuya.', '', 25549),
(121942, 'esES', '<El jinete del viento bate las alas como preludio de la inminente batalla>', '<El jinete del viento bate las alas como preludio de la inminente batalla>', 25549),
(121941, 'esES', 'El bosque te protege.', '', 25549),
(121940, 'esES', 'Contempla las hojas, camarada.', '', 25549),
(121939, 'esES', '¡Echaba de menos una buena charla!', '', 25549),
(121938, 'esES', '¿Qué es lo que buscas?', '', 25549),
(121937, 'esES', 'Todo a su tiempo.', '', 25549),
(121936, 'esES', 'Te mostraré lo que les ocurre a los héroes.', '', 25549),
(121935, 'esES', 'Yo te he avisado.', '', 25549),
(121934, 'esES', 'El abismo susurra tu nombre.', '', 25549),
(121933, 'esES', 'Si no puedo doblegar tu mente... ¡quebraré tus huesos!', '', 25549),
(121932, 'esES', 'No podrás detener lo que se aviene... Ni en tus sueños.', '', 25549),
(121931, 'esES', '¡La Pesadilla te consumirá!', '', 25549),
(121930, 'esES', '¡Tu tormento no tendrá fin!', '', 25549),
(121929, 'esES', '¿Morirías por esta patética tierra?', '', 25549),
(121928, 'esES', 'El maestro hará arder este mundo... ¡Y a ti con él!', '', 25549),
(121927, 'esES', '¿Buscas pelea? Permíteme...', '', 25549),
(121926, 'esES', 'No nos detendrás. ¡Somos legión!', '', 25549),
(121925, 'esES', '¡Sé presa de la oscuridad!', '', 25549),
(121924, 'esES', '¡Es inútil resistirse!', '', 25549),
(121923, 'esES', '¡No puedes huir del Señor de la Pesadilla!', '', 25549),
(121922, 'esES', 'Mis manos no son las únicas... manchadas de sangre...', '', 25549),
(121921, 'esES', '¡Esta es tu pesadilla!', '', 25549),
(121920, 'esES', 'Solo te aguarda... el terror...', '', 25549),
(121919, 'esES', 'Si no tienes esperanza, no puedes perderla.', '', 25549),
(121918, 'esES', 'La muerte... no nos detendrá...', '', 25549),
(121917, 'esES', '¡Mortal inútil! No puedes ganar...', '', 25549),
(121916, 'esES', 'Idiota... Esta tierra ya está condenada...', '', 25549),
(121915, 'esES', '¡Ríndete! Ya no queda esperanza...', '', 25549),
(121914, 'esES', '¿Llorarán por ti los elfos de la noche?', '', 25549),
(121913, 'esES', '¡Mi maestro destrozará tu alma!', '', 25549),
(121912, 'esES', 'Mi vida... por mi maestro...', '', 25549),
(121911, 'esES', 'La Pesadilla... me recibe...', '', 25549),
(121910, 'esES', '¡Esta tierra está perdida!', '', 25549),
(121909, 'esES', 'Tu mundo está... condenado...', '', 25549),
(121908, 'esES', 'No puedes... huir... de tus sueños...', '', 25549),
(121907, 'esES', 'Se mueve, sin rostro y en el olvido... Inmortal.', '', 25549),
(121906, 'esES', 'Te enviaré al sueño eterno.', '', 25549),
(121905, 'esES', 'Algún día lo entenderás.', '', 25549),
(121904, 'esES', 'No me hagas reír... ¡Pide ayuda!', '', 25549),
(121903, 'esES', 'La locura me arrastra al más allá.', '', 25549),
(121902, 'esES', 'La oscuridad... me aguarda...', '', 25549),
(121901, 'esES', 'Lástima. Podrías unirte a nosotros...', '', 25549),
(121900, 'esES', 'Maestro…', '', 25549),
(121899, 'esES', 'Raaarrgh...', '', 25549),
(121898, 'esES', '¡Pronto me suplicarás que te mate!', '', 25549),
(121897, 'esES', 'Muéstrame la caída de Archimonde frente a La Puerta Negra.', 'Muéstrame la caída de Archimonde frente a La Puerta Negra.', 25549),
(121896, 'esES', 'Muéstrame el Auge del Destructor en lo alto de la Ciudadela del Fuego Infernal.', 'Muéstrame el Auge del Destructor en lo alto de la Ciudadela del Fuego Infernal.', 25549),
(121895, 'esES', 'Muéstrame el Bastión de las Sombras de la Ciudadela del Fuego Infernal.', 'Muéstrame el Bastión de las Sombras de la Ciudadela del Fuego Infernal.', 25549),
(121894, 'esES', 'Muéstrame las Cámaras de Sangre de la Ciudadela del Fuego Infernal.', 'Muéstrame las Cámaras de Sangre de la Ciudadela del Fuego Infernal.', 25549),
(121893, 'esES', 'Muéstrame la Brecha Infernal, frente a las puertas de la Ciudadela del Fuego Infernal.', 'Muéstrame la Brecha Infernal, frente a las puertas de la Ciudadela del Fuego Infernal.', 25549),
(121892, 'esES', 'Muéstrame el Crisol de Puño Negro de la Fundición Roca Negra. ', 'Muéstrame el Crisol de Puño Negro de la Fundición Roca Negra. ', 25549),
(121891, 'esES', 'Muéstrame la Galería de Hierro de la Fundición Roca Negra.', 'Muéstrame la Galería de Hierro de la Fundición Roca Negra.', 25549),
(121890, 'esES', 'Muéstrame los Rescoldos de la Fundición Roca Negra.', 'Muéstrame los Rescoldos de la Fundición Roca Negra.', 25549),
(121889, 'esES', 'Muéstrame la Forja Negra de la Fundición Roca Negra.', 'Muéstrame la Forja Negra de la Fundición Roca Negra.', 25549),
(121888, 'esES', 'Muéstrame el Ascenso del Imperador en lo alto de Ogrópolis.', 'Muéstrame el Ascenso del Imperador en lo alto de Ogrópolis.', 25549),
(121887, 'esES', 'Muéstrame el Sagrario Arcano de Ogrópolis.', 'Muéstrame el Sagrario Arcano de Ogrópolis.', 25549),
(121886, 'esES', 'Muéstrame la Ciudad Amurallada de Ogrópolis.', 'Muéstrame la Ciudad Amurallada de Ogrópolis.', 25549),
(121885, 'esES', 'No bajes la guardia. Nos han pedido que demos prioridad a la seguridad de nuestros visitantes hasta que se calmen las cosas.', 'No bajes la guardia. Nos han pedido que demos prioridad a la seguridad de nuestros visitantes hasta que se calmen las cosas.', 25549),
(121884, 'esES', 'A su debido momento. Ahora tenemos que estar alerta.', 'A su debido momento. Ahora tenemos que estar alerta.', 25549),
(121883, 'esES', 'El entrenamiento continuará pronto, $n. Tienes mi palabra.', 'El entrenamiento continuará pronto, $n. Tienes mi palabra.', 25549),
(121882, 'esES', 'Me gustaría ayudarte a entrenar, pero este no es el momento. Te pido disculpas.', 'Me gustaría ayudarte a entrenar, pero este no es el momento. Te pido disculpas.', 25549),
(121881, 'esES', 'Me temo que no puedo ayudarte ahora mismo, $n. Nos han pedido que permanezcamos alerta en todo momento.', 'Me temo que no puedo ayudarte ahora mismo, $n. Nos han pedido que permanezcamos alerta en todo momento.', 25549),
(121880, 'esES', 'No te preocupes, el entrenamiento continuará. Pero ahora debemos centrarnos en asuntos más importantes.', 'No te preocupes, el entrenamiento continuará. Pero ahora debemos centrarnos en asuntos más importantes.', 25549),
(121879, 'esES', 'Lo siento, $n. Vuelve cuando las cosas se hayan calmado.', 'Lo siento, $n. Vuelve cuando las cosas se hayan calmado.', 25549),
(121878, 'esES', 'Lo que daría por echarle el guante a nuevos suministros.$B$BLlevará tiempo. Tenemos órdenes estrictas de no comprar, vender o comerciar hasta que se calmen las cosas.', 'Lo que daría por echarle el guante a nuevos suministros.$B$BLlevará tiempo. Tenemos órdenes estrictas de no comprar, vender o comerciar hasta que se calmen las cosas.', 25549),
(121877, 'esES', 'Lo siento, no puede ofrecerte nada ahora mismo.', 'Lo siento, no puede ofrecerte nada ahora mismo.', 25549),
(121876, 'esES', 'Disculpa, nos han mandado retener los suministros hasta nueva orden.', 'Disculpa, nos han mandado retener los suministros hasta nueva orden.', 25549),
(121875, 'esES', 'Lo siento. Mi mercancía no está disponible de momento.', 'Lo siento. Mi mercancía no está disponible de momento.', 25549),
(121874, 'esES', 'Me temo que no es el momento.', 'Me temo que no es el momento.', 25549),
(121873, 'esES', 'Te va a costar encontrar una tienda que esté abierta aún.', 'Te va a costar encontrar una tienda que esté abierta aún.', 25549),
(121872, 'esES', 'Mis disculpas. Los barcos de suministros están retenidos de momento.', 'Mis disculpas. Los barcos de suministros están retenidos de momento.', 25549),
(121871, 'esES', '¿Quién te ha dado su contrato? Ya me encargaré de eso más tarde. ¡Ve hacia allí!', '¿Quién te ha dado su contrato? Ya me encargaré de eso más tarde. ¡Ve hacia allí!', 25549),
(121870, 'esES', '¿No estás a mi servicio? Pero te puedo decir lo que hacer, ¿no?', '¿No estás a mi servicio? Pero te puedo decir lo que hacer, ¿no?', 25549),
(121869, 'esES', '¡Algún día yo seré tu maestro y tendrás que obedecerme!', '¡Algún día yo seré tu maestro y tendrás que obedecerme!', 25549),
(121868, 'esES', 'Este acuerdo es vinculante. Volveré.', 'Este acuerdo es vinculante. Volveré.', 25549),
(121867, 'esES', 'Mantente con vida hasta que vuelva a necesitarte.', 'Mantente con vida hasta que vuelva a necesitarte.', 25549),
(121866, 'esES', 'No temas. Ya te daré más instrucciones más adelante.', 'No temas. Ya te daré más instrucciones más adelante.', 25549),
(121865, 'esES', 'Aunque es muy divertido decirte lo que tienes que hacer... ya volveré más adelante y seguiremos.', 'Aunque es muy divertido decirte lo que tienes que hacer... ya volveré más adelante y seguiremos.', 25549),
(121864, 'esES', 'Qué patético. Ni mi antiguo maestro, ese asqueroso demonio eredar, recibía tantos golpes.', 'Qué patético. Ni mi antiguo maestro, ese asqueroso demonio eredar, recibía tantos golpes.', 25549),
(121863, 'esES', '¿Estás intentando que te den?', '¿Estás intentando que te den?', 25549),
(121862, 'esES', 'No se te da muy bien esto, ¿no?', 'No se te da muy bien esto, ¿no?', 25549),
(121861, 'esES', 'Daglop niega con la cabeza.', 'Daglop niega con la cabeza.', 25549),
(121860, 'esES', 'No, ¡te equivocas de objetivo!', 'No, ¡te equivocas de objetivo!', 25549),
(121859, 'esES', '¡Ataca, ataca, ataca!', '¡Ataca, ataca, ataca!', 25549),
(121858, 'esES', '¿Sabes quién es el guerrero más grande? Adivina.', '', 25549),
(121857, 'esES', 'He oído que hay piratas en El Cerdo Borracho. ¡Suena divertido!', '', 25549),
(121856, 'esES', 'Nunca uses un cuchillo de desuello para enfrentarte a un yeti.', '', 25549),
(121855, 'esES', 'Vuelve al trabajo.', '', 25549),
(121854, 'esES', 'Llega la caballería.', '', 25549),
(121853, 'esES', 'Nunca salgas con un tauren.', '', 25549),
(121852, 'esES', '¡Te podría contar tantas historias! Escaramuzas en Vallefresno, caos en las laderas del norte, surcar los cielos de Terrallende en dragón, un desayuno en Orgrimmar...', '', 25549),
(121851, 'esES', 'La Horda no es tan mala. Los gnomos, en cambio...', '', 25549),
(121850, 'esES', '', 'Este pueblo es... nuestro...', 25549),
(121849, 'esES', '', '¡No! ¡NO! Craaawwkk...', 25549),
(121848, 'esES', '', '¡Cobarde! Pagarás por esto...', 25549),
(121847, 'esES', '', '¡Yo te maldigo!', 25549),
(121846, 'esES', '', 'No... ¡Squaaggk!', 25549),
(121845, 'esES', '', 'Hermanas, vengadme...', 25549),
(121844, 'esES', '¡Ya tienes la cantidad máxima de sellos! Usa los que tienes antes de pedirme más.', '', 25549),
(121843, 'esES', '', '¡Craaawwkk!', 25549),
(121842, 'esES', '', '¡Nadie sobrevivirá!', 25549),
(121841, 'esES', '', '¡Scraaawk! ¡Que sangre!', 25549),
(121840, 'esES', 'Gracias por la ayuda. Te doy la potestad de hablar con los cazadores de demonios en mi nombre.', '', 25549),
(121839, 'esES', '', '¡Disfrutaré matándote!', 25549),
(121838, 'esES', '', '¡Arrancadle la piel! ¡Scraaawk!', 25549),
(121837, 'esES', '', '¡Squaaak! ¡Lo lamentarás!', 25549),
(121836, 'esES', '', 'Esta tierra... es nuestra...', 25549),
(121835, 'esES', '', '¡Arrancadle la piel a tiras!', 25549),
(121834, 'esES', '', '¡Squaaak! ¡Te haré pedazos!', 25549),
(121833, 'esES', '', 'Esta tierra... es nuestra...', 25549),
(121832, 'esES', '', '¡Sufre mi maldición!', 25549),
(121831, 'esES', '', 'Aah... ¡Yo te maldigo!', 25549),
(121830, 'esES', '', '¡Muere, idiota!', 25549),
(121829, 'esES', 'Pronto podré ofrecerte sellos de destino alterado a cambio de oro o recursos de la sede. Ahora mismo no tengo ninguno que ofrecerte.', '', 25549),
(121828, 'esES', '', 'No puedes... huir... de la maldición.', 25549),
(121827, 'esES', '', '¡Te despellejaré y esparciré tus huesos!', 25549),
(121826, 'esES', '', '¡Sangre y hueso a piedra y suelo!', 25549),
(121825, 'esES', '', '¡No nos detendrán!', 25549),
(121824, 'esES', '', '¡La bruja madre lo ordena!', 25549),
(121823, 'esES', '', '¡Crrggghaaawww!', 25549);

INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText_lang`, `FemaleText_lang`, `VerifiedBuild`) VALUES
(121822, 'esES', '', 'No... ¡No puede ser!', 25549),
(121821, 'esES', '', '¡Esta tierra es nuestra!', 25549),
(121820, 'esES', '', '¡No podemos permitir que escape!', 25549),
(121819, 'esES', '', '¡Hay que contenerlo!', 25549),
(121818, 'esES', '', '¡Debemos contenerlo a toda costa!', 25549),
(121817, 'esES', 'No nos consideres contrabandistas. Puedes llamarnos rescatadores profesionales.\n\nSomos expertos en rescates. Nos especializamos en restos flotantes, restos de naufragios, cosas abandonadas, ruinas y, por supuesto, recuperaciones arqueológicas exóticas.\n\nAh, no te acerques a la zona del templo que está al sur. Mis hombres están investigando posibles rescates y no quiero que te confundan con la competencia.\n\n<El señor Shackle hace el gesto de los Descoronados, te da el apretón de manos secreto y te guiña el ojo.>\n\nQuédate el tiempo que quieras.', '', 25549),
(121816, 'esES', '¿No lo es? P... ¡Pero este es el corazón de la maldad y la oscuridad del universo! ¡No puedes hablar en serio!', '', 25549),
(121815, 'esES', '¿Quieres gastar 50 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t p. de maná antiguo para obtener Guarda de la Primera Arcanista?', '¿Quieres gastar 50 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t p. de maná antiguo para obtener Guarda de la Primera Arcanista?', 25549),
(121814, 'esES', '<Obtén Guarda de la Primera Arcanista por 50 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t p. de maná antiguo.>', '<Obtén Guarda de la Primera Arcanista por 50 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t p. de maná antiguo.>', 25549),
(121813, 'esES', '¿Es una broma? Es broma, ¿verdad? Muy divertido.', '', 25549),
(121812, 'esES', 'Ah... $gmaestro:maestra;...', '', 25549),
(121811, 'esES', '|TInterface\\Icons\\inv_bannerpvp_01.blp:20|t Obtienes ¡|cFFFF0000|Hspell:224811|h[Por la Horda]|h|r!', '|TInterface\\Icons\\inv_bannerpvp_01.blp:20|t Obtienes ¡|cFFFF0000|Hspell:224811|h[Por la Horda]|h|r!', 25549),
(121810, 'esES', '¡Huye de la Mirada de la Legión!', '¡Huye de la Mirada de la Legión!', 25549),
(121809, 'esES', '¿Lo ves ahora? El destino de este mundo es inevitable. No se puede detener a la Legión.', '', 25549),
(121808, 'esES', 'Veamos qué órdenes te puedo dar hoy...', 'Veamos qué órdenes te puedo dar hoy...', 25549),
(121807, 'esES', 'Sabía que necesitabas más órdenes.', 'Sabía que necesitabas más órdenes.', 25549),
(121806, 'esES', 'Bien, te estaba buscando.', 'Bien, te estaba buscando.', 25549),
(121805, 'esES', 'Se me cansan los brazos.', 'Se me cansan los brazos.', 25549),
(121804, 'esES', 'Una leyenda asegura que algunos de nuestros antepasados de este mundo no son de la Legión. Seguro que son un rollo.', 'Una leyenda asegura que algunos de nuestros antepasados de este mundo no son de la Legión. Seguro que son un rollo.', 25549),
(121803, 'esES', '¿Sabes que en mi mundo se torturan diablillos por diversión? Yo era todo un experto.', '¿Sabes que en mi mundo se torturan diablillos por diversión? Yo era todo un experto.', 25549),
(121802, 'esES', 'La verdad es que este lugar es bastante agradable... ¡Vamos a quemar algo!', 'La verdad es que este lugar es bastante agradable... ¡Vamos a quemar algo!', 25549),
(121801, 'esES', '¿Esto es lo que haces con tu tiempo libre? Me parece una pérdida de tiempo.', '¿Esto es lo que haces con tu tiempo libre? Me parece una pérdida de tiempo.', 25549),
(121800, 'esES', '¡No digáis que no os avisé!', '', 25549),
(121799, 'esES', 'Me estoy controlando... ¡por ahora!', '', 25549),
(121798, 'esES', '¿Qué? ¡Para!', '', 25549),
(121797, 'esES', 'Luego te mato... Digo, ¡adiós!', '', 25549),
(121796, 'esES', 'Una retirada táctica, ¿eh?', '', 25549),
(121795, 'esES', '¡Hasta lueguito!', '', 25549),
(121794, 'esES', 'Si te sobra algún artefacto de valor incalculable que estuviera perdido en el tiempo, yo los colecciono.', '', 25549),
(121793, 'esES', '¡Seréis todos mis esclavos! Digo... quería decir... ¡Hola!', '', 25549),
(121792, 'esES', '¿Cuándo destruimos el mundo? ¿Pronto? Espero que sí.', '', 25549),
(121791, 'esES', 'A dormir y olvidar...', '', 25549),
(121790, 'esES', '¡Mi enjambre lo destruirá todo!', '', 25549),
(121789, 'esES', 'Por aquí... He encontrado algo.', '', 25549),
(121788, 'esES', 'Arluin te hace señas.', '', 25549),
(121787, 'esES', '', 'Hola, cielo. Kayn me ha pedido que ayude a traer a parte de tus tropas a este lugar. Espero que no te importe.\n\nParece que la Legión se ha establecido en aquella isla, y Kayn dice que deberíamos evitar que los demonios se hagan con toda Azsuna.\n\nNo te preocupes, traigo a los Illidari del Martillo Vil y los llevo de vuelta según dónde hagan falta. Tus tropas están listas para ir al instante adonde quieras.', 25549),
(121786, 'esES', '', 'Hola, cielo. Altruis me ha pedido que ayude a traer a parte de tus tropas a este lugar. Espero que no te importe.\n\nParece que la Legión se ha establecido en aquella isla, y Altruis dice que deberíamos evitar que los demonios se hagan con toda Azsuna.\n\nNo te preocupes, traigo a los Illidari del Martillo Vil y los llevo de vuelta según dónde hagan falta. Tus tropas están listas para ir al instante adonde quieras.', 25549),
(121785, 'esES', 'Nos rodearon como a ganado. No sé adónde nos están llevando, lo que sí sé es que no quiero ir. Te lo suplico...', 'Nos rodearon como a ganado. No sé adónde nos están llevando, lo que sí sé es que no quiero ir. Te lo suplico...', 25549),
(121784, 'esES', '¡No dejes que me cojan!', '¡No dejes que me cojan!', 25549),
(121783, 'esES', 'No quiero morir, pero matan a todo el que huye.', 'No quiero morir, pero matan a todo el que huye.', 25549),
(121782, 'esES', 'Todo el que sube a estos botes no regresa jamás... No dejes que me cojan, por favor.', 'Todo el que sube a estos botes no regresa jamás... No dejes que me cojan, por favor.', 25549),
(121781, 'esES', 'Por favor... Por favor, ayúdame...', 'Por favor... Por favor, ayúdame...', 25549),
(121780, 'esES', 'Disfruto del arte de gobernar. Se podría decir que tengo cierto talento.', '', 25549),
(121779, 'esES', 'Esta acción descontará 1200 p. de maná antiguo. ¿Quieres continuar?', 'Esta acción descontará 1200 p. de maná antiguo. ¿Quieres continuar?', 25549),
(121778, 'esES', 'Ofrecer: 1200x |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t|Hcurrency:1155|h|cFFFFFFFF Maná antiguo|h|r', 'Ofrecer: 1200x |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t|Hcurrency:1155|h|cFFFFFFFF Maná antiguo|h|r', 25549),
(121777, 'esES', 'Aunque ya he disfrutado de tu generosidad, debo insistir una vez más.\n\nYa sabes cómo funciona esto: la economía cambia, la gente muere en las calles... Es cuestión de negocios.\n\nMi precio es simple: todo el maná que lleves encima.\n\n<Arluin sonríe con dulzura.>\n\nA menos que no quieras mi ayuda, claro...', '', 25549),
(121776, 'esES', '', '$n, la Legión Ardiente nos está enviando a los demonios más poderosos de su arsenal. No piensan perder esta tercera guerra y no se detendrán ante nada hasta que todos desaparezcamos de la faz de Azeroth.\n\nNo temas, les devolveremos el favor.', 25549),
(121775, 'esES', '', '$n, ¿cómo va la pelea? ¿Necesitas suministros o que te repare algo?', 25549),
(121774, 'esES', 'Mis disculpas, $n. Estaba herido cuando vine aquí por primera vez en busca de las tropas de la Legión en Faronaar.\n\n¿Puedo hacer algo más por ti?', '', 25549),
(121773, 'esES', '', 'Gracias por salvarnos en Faronaar.\n\nNo me puedo creer que Cyana nos traicionara a todos, pero hay otros que también se han convertido en jurapenas. Les daremos caza y los mataremos junto a sus nuevos amos de la Legión.\n\n¡Lo juro!', 25549),
(121772, 'esES', 'Necesitamos que se concentren en derrotar a la Legión. Que se olviden de las viejas rencillas.', '', 25549),
(121771, 'esES', '', 'Gracias por tu ayuda en Faronaar, $n. Es una pena que uno de los nuestros acabara siendo un traidor para convertirse en uno de los jurapenas de la Legión Ardiente.\n\nLes haremos pagar.', 25549),
(121770, 'esES', 'Mientras tú lideras a tus fuerzas Illidari en su lucha contra los demonios, yo meditaré cuál debe ser nuestro siguiente paso aquí en Azsuna.\n\nDebemos localizar el Pilar de la Creación. Sé que tiene que estar por aquí.', '', 25549),
(121769, 'esES', 'Tenemos que bajar. Tus Illidari necesitan nuestra ayuda para destruir a la Legión Ardiente.\n\nDespués podremos volver a nuestros asuntos con el Pilar de la Creación en Azsuna.', '', 25549),
(121768, 'esES', 'Estamos en deuda contigo por tu ayuda en la lucha contra la Legión, $c.', '', 25549),
(121767, 'esES', 'Es un honor que hayas venido para ayudarnos a derrotar a la Legión Ardiente y conducirnos a la victoria.', '', 25549),
(121766, 'esES', '', 'Hola, $n. Si nos lideras, la Legión de Faronaar no tardará en caer.', 25549),
(121765, 'esES', '', 'Hola. ¿Vienes a ayudar a los Illidari a destruir a la Legión Ardiente?', 25549),
(121764, 'esES', '$n, me alegro de que estés aquí. La madre matriarca ha ofrecido transporte a nuestras tropas desde el Martillo Vil mientras intentábamos apuntalar aquí nuestras defensas.\n\nLa Legión Ardiente ha tomado Faronaar a través del istmo. Tengo un plan para contenerlos y masacrarlos antes de que infesten Azsuna por completo.\n\nMe vendría bien tu ayuda para llevar a los Illidari a la victoria.', '', 25549),
(121763, 'esES', '¿Necesitas que te arregle algo?', '', 25549),
(121762, 'esES', '', 'Adiós, campeones.', 25549),
(121761, 'esES', '', 'Tiene razón. No siento nada... No soy... nada.', 25549),
(121760, 'esES', '', 'Se acabó. Has perdido.', 25549),
(121759, 'esES', '', 'Por fin concluye mi larga caza. ¡Hoy se hará justicia!', 25549),
(121758, 'esES', '', 'Su furia no es nada comparada con la mía, Illidan. Tenemos asuntos pendientes.', 25549),
(121757, 'esES', 'Estoy listo.', 'Estoy lista.', 25549),
(121756, 'esES', '¡Tu trabajo formará a una nueva generación de astrólogos!', '', 25549),
(121755, 'esES', 'Si estudiáis sin descanso, ¡algún día me superaréis!', '', 25549),
(121754, 'esES', 'Parece que tus estudios progresan adecuadamente. Sigue así.', '', 25549),
(121753, 'esES', 'Te doy la bienvenida a mi taberna. Siento el desorden, no me sienta bien madrugar...', '', 25549),
(121752, 'esES', '', 'Gracias de nuevo por salvarme de esos gigantes de mar.', 25549),
(121751, 'esES', '¿Archimago Khadgar? ¿Y tú? ¡Qué sorpresa!', '', 25549),
(121750, 'esES', 'Qué arma más interesante tienes ahí. Si quieres ayudar, habla con Jace y con Allari.', '', 25549),
(121748, 'esES', '¡VA!', '¡VA!', 25549),
(121747, 'esES', '1', '1', 25549),
(121746, 'esES', '2', '2', 25549),
(121745, 'esES', '3', '3', 25549),
(121744, 'esES', '4', '4', 25549),
(121743, 'esES', '¡ATACANDO EN 5!', '¡ATACANDO EN 5!', 25549),
(121742, 'esES', '¡Hay que moverse!', '¡Hay que moverse!', 25549),
(121741, 'esES', '', 'Buen trabajo. No dudo de que será un honor para todos ellos contribuir a nuestra causa.', 25549),
(121740, 'esES', '', 'Tenemos que reforzar nuestras filas. Busca a los Marchitos y calma su ira. Yo los convocaré a Shal''Aran.', 25549),
(121739, 'esES', 'Deberías andarte con cuidado. Son tiempos peligrosos.', '', 25549),
(121738, 'esES', 'Este no es el momento.', '', 25549),
(121737, 'esES', '|TInterface\\Icons\\Spell_Fire_LavaSpawn:20|t ¡Xioliang sufre de |cFFFF0404|Hspell:224588|h[Calentamiento]|h|r! ¡Llévalo a la poza!', '|TInterface\\Icons\\Spell_Fire_LavaSpawn:20|t ¡Xioliang sufre de |cFFFF0404|Hspell:224588|h[Calentamiento]|h|r! ¡Llévalo a la poza!', 25549),
(121736, 'esES', 'Mmmmmm.', '', 25549),
(121735, 'esES', 'Mmm.', '', 25549),
(121734, 'esES', '', '¡Demasiado tarde, Illidari! ¡Hoja mácula, atacad!', 25549),
(121733, 'esES', '¡Observad el poder... del demonio interior!', '', 25549),
(121732, 'esES', 'Has ganado, Maiev. Pero la cazadora no es nada... sin su presa. Tú no eres nada... sin mí.', '', 25549),
(121731, 'esES', 'Maiev... ¿Cómo es posible?', '', 25549),
(121730, 'esES', '¡Mirad a los ojos del Traidor!', '', 25549),
(121729, 'esES', '¡Contemplad las llamas de Azzinoth!', '', 25549),
(121728, 'esES', '¡No me tocará una chusma como vosotros!', '', 25549),
(121727, 'esES', '¿Esto es todo, mortales? ¿Es esta toda la furia que podéis reunir?', '', 25549),
(121726, 'esES', '', '¡Hay más entre nosotros!', 25549),
(121725, 'esES', '', '¡No puedes ocultar tu naturaleza, demonio!', 25549),
(121724, 'esES', '', '¡El enemigo está entre nosotros!', 25549),
(121723, 'esES', 'Nunca lo olvidaré, Archidruida. Te doy las gracias.', 'Nunca lo olvidaré, Archidruida. Te doy las gracias.', 25549),
(121722, 'esES', 'Por la gracia de Elune, puedo continuar. Gracias, Archidruida.', 'Por la gracia de Elune, puedo continuar. Gracias, Archidruida.', 25549),
(121721, 'esES', 'Creía que había retornado a la tierra. Gracias, Archidruida.', 'Creía que había retornado a la tierra. Gracias, Archidruida.', 25549),
(121720, 'esES', 'Gracias, Archidruida. ¡Debemos ganar esta batalla!', 'Gracias, Archidruida. ¡Debemos ganar esta batalla!', 25549),
(121719, 'esES', 'Me siento rejuvenecer. Gracias.', 'Me siento rejuvenecer. Gracias.', 25549),
(121718, 'esES', 'Que Elune te bendiga.', 'Que Elune te bendiga.', 25549),
(121717, 'esES', 'Te doy la bienvenida.$b$bEsta cámara albergará un registro de tus logros. Los conjuntos de armadura chamánica y aspectos de arma que vayas adquiriendo se mostrarán aquí.$b$b¡Contamos contigo!', '', 25549),
(121716, 'esES', '¡La oscuridad abandona mi mente! ¡Vuelvo a estar completo! ¡Gracias, Nahlen''do!', '', 25549),
(121715, 'esES', 'La maldición... ha... ¡desaparecido! ¡Gracias, Nahlen''do!', '', 25549),
(121714, 'esES', '¡Mi mente vuelve a ser libre! ¡Estoy en deuda contigo, Nahlen''do!', '', 25549),
(121713, 'esES', '¿Esto es... real? ¡He recuperado el control de mí mismo! ¡$GBendito:Bendita; seas, Nahlen''do!', '', 25549),
(121712, 'esES', '¡Misericordiosa Elune, la ira ha desaparecido! ¡Gracias, Nahlen''do!', '', 25549),
(121711, 'esES', 'Nahlen''do, si te cruzas con más de los míos, te lo ruego, libéralos de la ira como hiciste conmigo.', '', 25549),
(121710, 'esES', '¡Es nuestra oportunidad! ¡Corred!', '', 25549),
(121709, 'esES', '¡Huid! ¡Estamos salvados!', '', 25549),
(121708, 'esES', '¡Corred mientras podáis!', '', 25549),
(121707, 'esES', 'Gracias, héroes.', '', 25549),
(121706, 'esES', '¡Haré lo que sea... déjame marchar!', '', 25549),
(121705, 'esES', '¡Soy inocente! ¡Apoyaba a la Gran Magistrix!', '', 25549),
(121704, 'esES', 'Por favor... Que alguien detenga esta locura.', '', 25549),
(121703, 'esES', 'Descubriremos quién se resiste a la Legión en Suramar. Confiesa y te mataré antes de que pierdas la cabeza.', '', 25549),
(121702, 'esES', 'Cuanto antes delates a tus aliados, antes cesará el dolor.', '', 25549),
(121701, 'esES', 'Mmm. ¿Sabeh, colega? Necesitah cambiar de aireh. Deberíah visitar loh Páramoh de Poniente, si te va el marrón.', '', 25549),
(121700, 'esES', 'Mmm. ¿Veh esoh árboleh de ahí? Dicen que son muy ohcuroh, colega. Y dicen que lo ohcuro eh malo.', '', 25549),
(121699, 'esES', 'Mmm. Sabeh, colega, dicen qu''ehte sitio eh muy marrón. Sé de muchoh sitioh máh verdeh que ehte.', '', 25549),
(121697, 'esES', 'Mmm. Dicen que esah cahcadah son muy rápidah, colega. No se sabe de dónde vienen ni a dónde van.', '', 25549),
(121696, 'esES', 'Ese viejo toro ehtá ehtancado en suh viejah cohtumbreh. Pienso ponerle remedio, colega.$b$bEhte mundo tiene verdadeh durah. Verdadeh que te quitarían la sonrisa de la cara máh rápido que un bofetón de tu madre.', '', 25549),
(121695, 'esES', 'No recuerdo qué ocurrió después, salvo que algunos de los míos y yo despertamos y viajamos en manada por el Sueño Esmeralda. Transcurrido un tiempo, llegamos a esta tierra y nos separamos.', '', 25549),
(121694, 'esES', 'Recuerdo cuando el mundo era más sencillo. Se era un héroe solo por alejar a los kóbolds del hogar.$b$bRecuerdo una época en la que se respetaba a los mayores, antes de que llegase ese trol con su comportamiento... trol.', '', 25549),
(121693, 'esES', '', 'Los druidas Feral se sirven del cambio de forma. En forma felina, podrás destripar y desangrar a los enemigos con tus zarpas y colmillos.', 25549),
(121692, 'esES', '¡He resbalado! ¡Perdóname!', '', 25549),
(121691, 'esES', '¡Este cargamento vale más que tú! ¡Cómo osas tener tan poco cuidado!', '', 25549),
(121690, 'esES', 'El velo de mis ojos ha caído al fin, héroes. Las sombras retroceden y el Sueño llama.', '', 25549),
(121689, 'esES', '¡Archimonde, no darás un paso más! ¡La mismísima alma de Azeroth se alza contra ti!', '', 25549),
(121688, 'esES', '', 'Si los ciudadanos no obedecen, gobernaremos mediante la fuerza y el miedo. ¡La resistencia a la Gran Magistrix se acabará!', 25549),
(121687, 'esES', '', 'Hay traidores a la Gran Magistrix ocultos bajo nuestras narices. ¡Los encontraremos y acabaremos con la resistencia!', 25549),
(121686, 'esES', 'Tu rápida intervención ha salvado muchas vidas. Estamos en deuda contigo.', '', 25549),
(121685, 'esES', 'Tengo una importante misión para ti. Es una seria amenaza para la resistencia.', '', 25549),
(121683, 'esES', '¡Mis manos! ¡Mis piernas! ¡Vuelvo a estar completo! Espera... ¿Es la Guadaña de Elune? Gracias por liberarme, Nahlen''do.', '', 25549),
(121682, 'esES', 'Aún estoy confuso, pero recuerdo una pelea... Ah, sí... luchábamos contra el sátiro cuando la ira se apoderó de mí.', '', 25549),
(121681, 'esES', '¡Ya no soy presa de la ira! Gracias a Elune que me has encontrado, adalid del colmillo; o, como decimos en la manada, Nahlen''do.', '', 25549),
(121680, 'esES', 'Vuelvo... ¡Vuelvo a ser yo mismo! ¡Gracias, Nahlen''do! Que la ira nunca se apodere de ti.', '', 25549),
(121679, 'esES', '¡Yo-ho, yo-ho, con diez cañones por banda...!', '', 25549),
(121678, 'esES', '¿El IV:7 navega con esos bergantes de La Hoja Roja? ¡Rayos y centellas!', '', 25549),
(121677, 'esES', '¡Arr! Ya tenemos nuestro botín. Zarpa hacia Dalaran, luego te alcanzo.', '', 25549),
(121676, 'esES', 'Contesta o te paso por la quilla: ¿quién te envía?', '', 25549),
(121675, 'esES', '¡Tethys, de los Bucaneros Velasangre!', '', 25549),
(121674, 'esES', 'Arr, nos quieren truhanear con estos garabatos. ¡Esto es obra de un letrado!', '', 25549),
(121673, 'esES', 'Estas no son aguas de La Hoja Roja... ¿Quién es tu capitán, grumete?', '', 25549),
(121672, 'esES', 'Tú ve a por cecina... Yo encontraré marineros de agua dulce.', '', 25549),
(121671, 'esES', '¡Ese es el pabellón de La Hoja Roja! De eso no hay duda...', '', 25549),
(121670, 'esES', 'Levaré anclas para buscar pistas. ¡Nos vemos allí!', '', 25549),
(121669, 'esES', 'Conozco la Bahía de Cuarzo como mi propio camarote, ya lo creo que sí.', '', 25549),
(121668, 'esES', '¡Yo me encargo de estos chuchos! ¡Atacad ahora, amigos! ¡Atacad al Traidor!', '', 25549),
(121667, 'esES', 'Venid, esbirros míos. ¡Dad a este traidor su merecido!', '', 25549),
(121665, 'esES', '¡¿Hola!? ¿Por qué me ha matado?', '¡¿Hola?! ¿Por qué me ha matado? ¡Estaba SUPERLEJOS!', 25549),
(121664, 'esES', 'Me he despistado.', 'Me he despistado.', 25549),
(121663, 'esES', '¡¿No tenía una piedra de alma?!', '¡¿No tenía una piedra de alma?!', 25549),
(121662, 'esES', '¿Hay más resurrecciones?', '¿Hay más resurrecciones?', 25549),
(121661, 'esES', 'Renacer, plis.', 'Renacer, plis.', 25549),
(121660, 'esES', '¡Res, porfa!', '¡Res, porfa!', 25549),
(121659, 'esES', 'Ay.', 'Ay.', 25549),
(121658, 'esES', '¿Quieres gastar 10 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t p. de maná antiguo para obtener Maestría de líneas Ley?', '¿Quieres gastar 10 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t p. de maná antiguo para obtener Maestría de líneas Ley?', 25549),
