(116810, 'esES', '¡Parad! ¡No reparéis en gastos!', '¡Parad! ¡No reparéis en gastos!', 25549),
(116809, 'esES', 'Tenu''balah.', '', 25549),
(116808, 'esES', '', 'No es una criatura cualquiera. ¡El mismísimo Odyn designó su cargo!', 25549),
