(116805, 'esES', 'Saludos.', '', 25549),
(116804, 'esES', '¿Una criatura mortal al mando del Bastión Celestial? ¡Qué blasfemia!', '', 25549),
(116803, 'esES', '¡Hodir! He traído refuerzos. ¡Estos canallas no son rival para nosotros!', '', 25549),
(116802, 'esES', '¡Lo lamentaréis!', '', 25549),
(116801, 'esES', '¡Este no es tu lugar, demonio! ¡Fuera!', '', 25549),
(116800, 'esES', '¡Por Ulduar!', '', 25549),
(116799, 'esES', '¡Tu presencia profana este templo, demonio!', '', 25549),
(116798, 'esES', '¡Morid, alimañas!', '', 25549),
(116793, 'esES', '¡Es inútil!', 'Es inútil resistir...', 25549),
(116792, 'esES', '¡Los Nocheterna gobernarán este mundo!', '¡Los shal''dorei gobernarán este mundo!', 25549),
