(116678, 'esES', '¡Voy a liquidarte, escoria!', '', 25549),
(116677, 'esES', '¡Es la era de los shal''dorei!', '', 25549),
(116676, 'esES', '¡Siente el poder de los shal''dorei!', '', 25549),
(116675, 'esES', '¡La suerte está echada!', '', 25549),
(116674, 'esES', '¡Fuera, miserables!', '', 25549),
(116673, 'esES', '¡Por los shal''dorei!', '', 25549),
(116672, 'esES', '¡No podéis hacernos daño!', '', 25549),
(116671, 'esES', '¡No pasaréis!', '', 25549),
(116670, 'esES', '¡Por Suramar!', '', 25549),
(116669, 'esES', '¡Debemos proteger nuestras tierras!', '', 25549),
(116668, 'esES', '¡No pasaréis!', '¡Fuera, miserables!', 25549),
(116667, 'esES', '¡Por Suramar!', '¡Por Suramar! ¡Por Elisande!', 25549),
(116666, 'esES', '¡Debemos proteger nuestras tierras!', '¡Debemos proteger nuestras tierras!', 25549),
(116665, 'esES', '¡Fuera, miserables!', '¡Largo, demonios!', 25549),
(116664, 'esES', '¡Por los shal''dorei!', '¡Por Suramar!', 25549),
(116663, 'esES', '¡No podéis hacernos daño!', '¡Debemos contenerlos aquí!', 25549),
(116662, 'esES', '¡Largo, demonios!', '¡No pasaréis!', 25549),
(116661, 'esES', '¡Por Suramar! ¡Por Elisande!', '¡Por los shal''dorei!', 25549),
(116660, 'esES', '¡Debemos contenerlos aquí!', '¡No podéis hacernos daño!', 25549),
(116659, 'esES', 'No me encuentro bien...', '', 25549),
(116658, 'esES', 'Uf, ¿qué ocurre?', '', 25549),
