UPDATE `broadcast_text_locale` SET `FemaleText_lang`='Nos vendría bien $gun:una; $c. Me alegro de que mi marido te enviara.\n\nSoy exploradora, no estoy hecha para el combate cuerpo a cuerpo. Y Lao-Chen... bueno, normalmente es un luchador, pero todavía está exhausto de su última batalla.\n\nAdemás, está muy ocupado elaborando algún plan.', `VerifiedBuild`=25549 WHERE (`ID`=61501 AND `locale`='esES');
