UPDATE `broadcast_text_locale` SET `MaleText_lang`='Ah, ha sido una batalla complicada. Es una pena haber perdido amigos.\n\nNo obstante, me alegro de haberles ordenado construir el dispositivo de refresco en el campo de batalla.\n\nSin él y sin la fuerza de mi cerveza negra, quién sabe cuánta gente más habría perecido...', `VerifiedBuild`=25549 WHERE (`ID`=61494 AND `locale`='esES');
