UPDATE `broadcast_text_locale` SET `MaleText_lang`='Alguien debe detener a Químicos La Corona S.L. Apuesto mi cohete abisal chapado en oro a que están fabricando la próxima gran plaga con el dinero de los ciudadanos adictos al chocolate...\n\n¡Ojalá encontrara a alguien que entregue los papeles del juzgado a sus boticarios! Entonces acabaríamos con esto... y ya que estamos, ¡quizá podríamos confiscar sus activos!', `VerifiedBuild`=25549 WHERE (`ID`=40428 AND `locale`='esES');
