UPDATE `broadcast_text_locale` SET `MaleText_lang`='¡Por la Horda!\n\nCoge armas de los cajones que nos rodean y preséntate en el Martillo de Agmar, al este de aquí. Tu primera prueba como miembro de la Horda es sobrevivir al viaje.\n\n¡Lok''tar ogar!', `FemaleText_lang`='¡Por la Horda!\n\nCoge armas de los cajones que nos rodean y preséntate en el Martillo de Agmar, al este de aquí. Tu primera prueba como miembro de la Horda es sobrevivir al viaje.\n\n¡Lok''tar ogar!', `VerifiedBuild`=25549 WHERE (`ID`=25655 AND `locale`='esES');
