UPDATE `broadcast_text_locale` SET `MaleText_lang`='Cierto, la reunión. Vayamos al grano, entonces.$B$BEl hecho es que la madera y el ganado que se está reuniendo de la Foresta Ruuan, de lo que tú eres responsable, ha disminuido sobremanera.$B$B¡Necesitamos esos recursos, pero has permitido que los druidas de la Expedición Cenarion se interpongan en nuestro camino!', `VerifiedBuild`=25549 WHERE (`ID`=19684 AND `locale`='esES');
