UPDATE `broadcast_text_locale` SET `MaleText_lang`='¿Negociaciones? ¡NEGOCIACIONES!$B$BPermíteme dejar totalmente clara nuestra postura. Somos un pueblo libre, capaz de hacer lo que queramos y movernos como nos plazca. La Expedición Cenarion no es dueña de esta cadena montañosa.$B$B¡No habrá negociaciones! Ahora vuelve con los druidas y diles que seguiremos haciendo lo que nos plazca.', `VerifiedBuild`=25549 WHERE (`ID`=19663 AND `locale`='esES');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Sobrestante, estoy aquí para negociar en nombre de la Expedición Cenarion.', `FemaleText_lang`='Sobrestante, estoy aquí para negociar en nombre de la Expedición Cenarion.', `VerifiedBuild`=25549 WHERE (`ID`=19662 AND `locale`='esES');
UPDATE `broadcast_text_locale` SET `MaleText_lang`='Las Montañas Filospada son un lugar de grandes oportunidades. Qué mala suerte que algunos consideren estar por encima de los demás en asuntos que se refieren a aprovecharse de tales oportunidades.$B$B¿Quién se cree que es la Expedición Cenarion para decirnos lo que podemos o no podemos hacer aquí?', `VerifiedBuild`=25549 WHERE (`ID`=19661 AND `locale`='esES');
